import { useEffect, useState } from 'react';
import { ForumPost } from '../types';
import { loadForumPostsFromChat } from '../utils/forumParser';
import { FORUM_STATE_EVENT, readForumState } from '../utils/forumGeneration';
import { useMvuSnapshot } from './useMvuData';

export function useForumPosts(): ForumPost[] {
  const mvuData = useMvuSnapshot();
  const [posts, setPosts] = useState<ForumPost[]>(() => {
    const stored = readForumState().posts;
    return stored.length ? stored : loadForumPostsFromChat(mvuData.时间);
  });

  useEffect(() => {
    let cancelled = false;
    const sync = () => {
      const stored = readForumState().posts;
      const next = stored.length ? stored : loadForumPostsFromChat(mvuData.时间);
      if (cancelled) return;
      setPosts(prev => _.isEqual(prev, next) ? prev : next);
    };

    sync();
    const timer = window.setInterval(sync, 800);

    try {
      eventOn(tavern_events.MESSAGE_RECEIVED, sync);
      eventOn(tavern_events.MESSAGE_UPDATED, sync);
      eventOn(tavern_events.CHAT_CHANGED, sync);
      window.addEventListener(FORUM_STATE_EVENT, sync);
    } catch {
      // ignore
    }

    return () => {
      cancelled = true;
      window.clearInterval(timer);
      window.removeEventListener(FORUM_STATE_EVENT, sync);
    };
  }, [mvuData.时间]);

  return posts;
}
