import { CachedImage } from '../shared/CachedImage';
import React, { useState } from 'react';

import { CampusBuilding, CampusZone, Character, SchoolRule, BuildingEvent, BuildingEventStage } from '../../types';
import { BottomSheetModal, CenterModal } from '../ui/Modal';
import { Map, Info, Calendar, Users, BookOpen, Plus, Clock, ChevronDown, ChevronUp, Edit3, Heart, GraduationCap, MapPin } from 'lucide-react';
import { AnimatePresence, motion } from 'framer-motion';
import { showToast } from '../ui/Toast';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';
import { RuleCard } from '../shared/RuleCard';
import { DateTimePickerModal } from '../shared/DateTimePickerModal';
import { Card } from '../ui/Card';
import { fillTavernInput } from '../../utils/fillTavernInput';
import { isTimestampInRange } from '../../utils/forumParser';
import { useCampusTheme } from '../../hooks/useCampusTheme';

interface BuildingDetailsModalProps {
  building: CampusBuilding;
  onBuildingsChange: (buildings: CampusBuilding[]) => void;
  characters: Character[];
  rules: SchoolRule[];
  buildings: CampusBuilding[];
  nowTs: number;
  onClose: () => void;
  onCharacterClick: (char: Character) => void;
}

type TabType = 'info' | 'places' | 'events' | 'characters' | 'rules';

export const BuildingDetailsModal: React.FC<BuildingDetailsModalProps> = ({ building: initialBuilding, characters, buildings, rules, nowTs, onClose, onCharacterClick }) => {
  // Always derive latest building from `buildings` list
  const building = buildings.find(b => b.id === initialBuilding.id) || initialBuilding;
  const { isDark } = useCampusTheme();

  const activeEvents = (building.events || []).filter(e => isTimestampInRange(nowTs, e.startTime, e.endTime));
  const [activeTab, setActiveTab] = useState<TabType>('info');
  const [placeName, setPlaceName] = useState('');
  const [placeType, setPlaceType] = useState('其他');
  const [placeDescription, setPlaceDescription] = useState('');
  const [placeZoneId, setPlaceZoneId] = useState('');
  const [editingPlaceId, setEditingPlaceId] = useState<string | null>(null);
  const [zoneName, setZoneName] = useState('');
  const [zoneType, setZoneType] = useState('楼层');
  const [showZoneForm, setShowZoneForm] = useState(false);
  const [placeEditorMode, setPlaceEditorMode] = useState<'add' | 'edit' | null>(null);
  const [expandedZones, setExpandedZones] = useState<string[]>([]);
  const [draftZones, setDraftZones] = useState<CampusZone[]>([]);
  const availableZones = [...(building.zones || []), ...draftZones.filter(zone => !(building.zones || []).some(item => item.name === zone.name))];
  const resetPlaceForm = () => {
    setPlaceName('');
    setPlaceType('其他');
    setPlaceDescription('');
    setPlaceZoneId('');
    setEditingPlaceId(null);
    setDraftZones([]);
    setZoneName('');
    setZoneType('楼层');
    setShowZoneForm(false);
  };
  const closePlaceEditor = () => {
    setPlaceEditorMode(null);
    setShowZoneForm(false);
    resetPlaceForm();
  };
  const selectPlace = (id: string) => {
    const place = building.places?.find(item => item.id === id);
    if (!place) {
      resetPlaceForm();
      return;
    }
    setEditingPlaceId(place.id);
    setPlaceName(place.name);
    setPlaceType(place.type);
    setPlaceDescription(place.description || '');
    setPlaceZoneId(place.zoneId || '');
  };
  const submitPlace = (event: React.FormEvent) => {
    event.preventDefault();
    const places = building.places || [];
    const name = placeName.trim();
    if (!name || (placeEditorMode === 'edit' && !editingPlaceId)) return;
    if (places.some(place => place.id !== editingPlaceId && place.name.trim() === name)) {
      showToast('该建筑中已有同名地点', 'error');
      return;
    }
    const existing = places.find(place => place.id === editingPlaceId);
    if (placeEditorMode === 'edit' && !existing) {
      showToast('原地点已变化，请重新选择', 'error');
      return;
    }
    const zone = availableZones.find(item => item.id === placeZoneId);
    const details = JSON.stringify({ 名称: name, 所属分区: zone?.name || '', 类型: placeType.trim() || '其他', 描述: placeDescription.trim() });
    const operation = existing
      ? `修改「${building.name}」内原名为「${existing.name}」的地点，改为：${details}。保留该地点其他属性；若名称变化，同步更新该建筑内玩家和角色引用此地点的「当前具体地点」。`
      : `在「${building.name}」内新增地点：${details}。名称在该建筑内唯一，其他属性采用默认值。`;
    const newZones = draftZones.filter(item => !(building.zones || []).some(current => current.name === item.name));
    const zoneCommand = newZones.length
      ? `先在该建筑新增以下分区（已有同名分区则复用）：${JSON.stringify(newZones.map(item => ({ 名称: item.name, 类型: item.type, 排序: item.order })))}。`
      : '';
    const command = `${operation}${zoneCommand}请通过 MVU 变量更新写入「校园建筑」中对应建筑的地点及分区，不生成地点或分区 ID，不覆盖其他地点、分区和建筑数据。`;
    if (!fillTavernInput(command)) {
      showToast('未能写入酒馆输入栏，请重试；表单内容已保留', 'error');
      return;
    }
    showToast(existing ? '修改地点指令已写入输入栏，发送后等待 AI 更新' : '新增地点指令已写入输入栏，发送后等待 AI 更新', 'success');
    closePlaceEditor();
  };
  const placeSelectClass = 'place-select w-full appearance-none rounded-xl border border-border-default bg-surface-solid py-3 pl-3 pr-10 text-sm font-medium text-text-primary shadow-sm outline-none transition focus:border-[color:var(--action-text)] focus:ring-2 focus:ring-[color:var(--action-text)]/20';
  const placeGroups = [...(building.zones || [])]
    .sort((a, b) => a.order - b.order)
    .map(zone => ({
      id: zone.id, name: zone.name,
      places: (building.places || []).filter(place => place.zoneId === zone.id),
    }));
  const ungroupedPlaces = (building.places || []).filter(place =>
    !place.zoneId || !(building.zones || []).some(zone => zone.id === place.zoneId),
  );
  if (ungroupedPlaces.length) {
    placeGroups.push({ id: '__ungrouped__', name: '未分区地点', places: ungroupedPlaces });
  }

  
  const dragProps = useDraggableScroll<HTMLDivElement>();
  
  // Adding event form state
  const [isAddingEvent, setIsAddingEvent] = useState(false);
  const [newEventName, setNewEventName] = useState('');
  const [newEventDesc, setNewEventDesc] = useState('');
  const [newEventStart, setNewEventStart] = useState('');
  const [newEventEnd, setNewEventEnd] = useState('');
  const [newEventStages, setNewEventStages] = useState<BuildingEventStage[]>([]);
  
  const [newStageName, setNewStageName] = useState('');
  const [newStageDesc, setNewStageDesc] = useState('');
  const [newStageStart, setNewStageStart] = useState('');
  const [newStageEnd, setNewStageEnd] = useState('');
  const [editingEvent, setEditingEvent] = useState<BuildingEvent | null>(null);
  const [expandedEventId, setExpandedEventId] = useState<string | null>(null);
  
  const area = building.width * building.height;
  let sizeLabel = '未知';
  if (area === 1) sizeLabel = '小型';
  else if (area >= 2 && area <= 4) sizeLabel = '中型';
  else if (area >= 5 && area <= 9) sizeLabel = '大型';
  else if (area >= 10 && area <= 16) sizeLabel = '超大型';
  else if (area > 16) sizeLabel = '超大型';

  const activeCharacters = characters.filter(c => c.location === building.name && !c.isHidden);
  
  const buildingRules = rules.filter(r => {
    const isGlobal = !r.locationNames || r.locationNames.length === 0 || r.locationNames.includes('全校');
    if (isGlobal) return false;
    return r.locationNames?.includes(building.name);
  });

  const formatTime = (timestamp: number) => {
    const d = new Date(timestamp);
    return `${d.getMonth()+1}月${d.getDate()}日 ${d.getHours().toString().padStart(2,'0')}:${d.getMinutes().toString().padStart(2,'0')}`;
  };

  const toPickerValue = (timestamp: number) => {
    const d = new Date(timestamp);
    if (Number.isNaN(d.getTime())) return '';
    const month = `${d.getMonth() + 1}`.padStart(2, '0');
    const day = `${d.getDate()}`.padStart(2, '0');
    const hour = `${d.getHours()}`.padStart(2, '0');
    const minute = `${d.getMinutes()}`.padStart(2, '0');
    return `${d.getFullYear()}-${month}-${day}T${hour}:${minute}`;
  };

  const resetEventForm = () => {
    setIsAddingEvent(false);
    setEditingEvent(null);
    setNewEventName('');
    setNewEventDesc('');
    setNewEventStart('');
    setNewEventEnd('');
    setNewEventStages([]);
    setNewStageName('');
    setNewStageDesc('');
    setNewStageStart('');
    setNewStageEnd('');
  };

  const openEditEvent = (event: BuildingEvent) => {
    setEditingEvent(event);
    setIsAddingEvent(true);
    setNewEventName(event.name);
    setNewEventDesc(event.description || '');
    setNewEventStart(toPickerValue(event.startTime));
    setNewEventEnd(toPickerValue(event.endTime));
    setNewEventStages((event.stages || []).map(stage => ({ ...stage })));
    setNewStageName('');
    setNewStageDesc('');
    setNewStageStart('');
    setNewStageEnd('');
  };

  /** 若下方环节草稿已填写完整，一并纳入（避免只填了表单却未点「确认添加环节」导致丢失） */
  const collectEventStages = (): BuildingEventStage[] | null => {
    const stages = [...newEventStages];
    const draftName = newStageName.trim();
    const hasDraft =
      Boolean(draftName) || Boolean(newStageDesc.trim()) || Boolean(newStageStart) || Boolean(newStageEnd);

    if (!hasDraft) return stages;

    if (!draftName || !newStageStart || !newStageEnd) {
      showToast('请填写完整环节信息，或清空未完成的环节草稿', 'error');
      return null;
    }
    const startTs = new Date(newStageStart).getTime();
    const endTs = new Date(newStageEnd).getTime();
    if (Number.isNaN(startTs) || Number.isNaN(endTs) || startTs >= endTs) {
      showToast('环节结束时间必须晚于开始时间', 'error');
      return null;
    }
    stages.push({
      id: Date.now().toString(),
      name: draftName,
      description: newStageDesc.trim(),
      startTime: startTs,
      endTime: endTs,
    });
    return stages;
  };

  const formatStagesCommand = (stages: BuildingEventStage[]) => {
    if (!stages.length) return '';
    const lines = stages.map((stage, index) => {
      const desc = stage.description?.trim() || '无';
      return `${index + 1}. 环节名称：${stage.name}；开始时间：${formatTime(stage.startTime)}；结束时间：${formatTime(stage.endTime)}；环节描述：${desc}`;
    });
    return `；活动环节如下：${lines.join('；')}`;
  };

  const buildEventCommand = (mode: 'add' | 'edit', stages: BuildingEventStage[]) => {
    const name = newEventName.trim();
    const desc = newEventDesc.trim() || '无';
    const startTs = new Date(newEventStart).getTime();
    const endTs = new Date(newEventEnd).getTime();
    const stagesText = formatStagesCommand(stages);
    const body = `活动名称：${name}，开始时间：${formatTime(startTs)}，结束时间：${formatTime(endTs)}，活动描述：${desc}${stagesText}。请写入「${building.name}」的建筑活动${stages.length ? '（含活动环节）' : ''}。`;
    if (mode === 'edit' && editingEvent) {
      return `将「${building.name}」中的「${editingEvent.name}」活动修改为：${body}`;
    }
    return `在「${building.name}」添加活动：${body}`;
  };

  const handleAddStage = () => {
    if (!newStageName || !newStageStart || !newStageEnd) {
      showToast('请填写完整环节信息', 'error');
      return;
    }
    const startTs = new Date(newStageStart).getTime();
    const endTs = new Date(newStageEnd).getTime();
    if (startTs >= endTs) {
      showToast('结束时间必须晚于开始时间', 'error');
      return;
    }
    const stage: BuildingEventStage = {
      id: Date.now().toString(),
      name: newStageName,
      description: newStageDesc,
      startTime: startTs,
      endTime: endTs
    };
    setNewEventStages([...newEventStages, stage]);
    setNewStageName('');
    setNewStageDesc('');
    setNewStageStart('');
    setNewStageEnd('');
  };

  const handleSubmitEvent = () => {
    if (!newEventName.trim() || !newEventStart || !newEventEnd) {
      showToast('请填写完整活动信息', 'error');
      return;
    }
    const startTs = new Date(newEventStart).getTime();
    const endTs = new Date(newEventEnd).getTime();
    if (Number.isNaN(startTs) || Number.isNaN(endTs) || startTs >= endTs) {
      showToast('活动结束时间必须晚于开始时间', 'error');
      return;
    }

    const stages = collectEventStages();
    if (!stages) return;

    const text = buildEventCommand(editingEvent ? 'edit' : 'add', stages);
    if (!fillTavernInput(text)) {
      showToast('未能写入酒馆输入栏，请手动复制操作文本', 'error');
      return;
    }
    showToast(editingEvent ? '已写入修改活动的操作文本' : '已写入添加活动的操作文本', 'success');
    resetEventForm();
  };

  const toggleExpandEvent = (id: string) => {
    setExpandedEventId(prev => prev === id ? null : id);
  };

  return (
    <BottomSheetModal 
      hideDragHandle={placeEditorMode !== null}
      isOpen={true} 
      onClose={onClose}
      className="p-0 bg-surface-solid rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.1)] z-[100] h-[75%] max-h-full flex flex-col"
    >
      <style>
        {`
          @keyframes marquee {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
          }
          .animate-marquee-slow {
            animation: marquee 8s linear infinite;
            display: inline-block;
            white-space: nowrap;
          }
        `}
      </style>
      <div className="p-6 pb-2 shrink-0 border-b border-border-default/30 rounded-t-3xl z-20">
        <div className="flex items-center justify-between">
          <h2 className="text-2xl font-bold text-text-primary flex items-center gap-2">
            <Map className="w-6 h-6 text-[color:var(--action-text)]" />
            {building.name}
          </h2>
          <button 
            onClick={onClose}
            className="p-2 bg-surface rounded-full text-text-secondary hover-fill transition-colors"
          >
            <ChevronDown className="w-5 h-5" />
          </button>
        </div>
        
        <div className="grid grid-cols-5 gap-1.5 mt-4 p-1 rounded-2xl bg-surface border border-border-default">
          {[
            { id: 'info', icon: Info, label: '信息' },
            { id: 'places', icon: MapPin, label: '地点' },
            { id: 'events', icon: Calendar, label: '活动' },
            { id: 'characters', icon: Users, label: '角色' },
            { id: 'rules', icon: BookOpen, label: '规则' }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as TabType)}
              className={`flex items-center justify-center gap-1 py-2 text-xs font-bold rounded-xl transition-colors ${
                activeTab === tab.id
                  ? 'bg-surface-solid text-[color:var(--action-text)] shadow-sm'
                  : 'text-text-secondary hover-fill'
              }`}
            >
              <tab.icon className="w-3.5 h-3.5" />
              {tab.label}
            </button>
          ))}
        </div>
      </div>
      
      <div 
        className="flex-1 overflow-y-auto overflow-x-hidden p-6 pb-32 space-y-6 hide-scrollbar relative z-10 select-none cursor-grab active:cursor-grabbing touch-none"
        {...dragProps} ref={dragProps.ref}
      >
        <AnimatePresence mode="wait">
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.2 }}
            className="h-full pointer-events-auto"
          >
            {/* ================= INFO TAB ================= */}
            {activeTab === 'info' && (
              <div className="space-y-6">
                <div>
                  <h3 className="text-sm font-bold text-text-secondary mb-2 uppercase tracking-widest">建筑简介</h3>
                  <div className="bg-surface-solid p-4 rounded-2xl shadow-sm border border-border-default text-text-primary leading-relaxed text-sm">
                    {building.description || '暂无详细介绍。'}
                  </div>
                </div>
                
                <div>
                  <div className="flex items-center justify-between bg-surface-solid p-4 rounded-2xl shadow-sm border border-border-default">
                    <span className="text-sm font-bold text-text-secondary">建筑大小</span>
                    <span className="text-sm font-black text-text-primary text-right">
                      {sizeLabel}（宽 {building.width} × 长 {building.height}）
                    </span>
                  </div>
                </div>
                
                <div>
                  <h3 className="text-sm font-bold text-text-secondary mb-2 uppercase tracking-widest">当前活动</h3>
                  {activeEvents.length === 0 ? (
                    <div className="bg-surface border border-dashed border-border-default p-6 rounded-2xl flex flex-col items-center justify-center gap-2 text-text-secondary">
                      <Calendar className="w-8 h-8 opacity-50" />
                      <span className="text-sm font-bold">此处没有正在进行的活动</span>
                    </div>
                  ) : (
                    <div className="space-y-4">
                      {activeEvents.map(event => {
                        const isExpanded = expandedEventId === event.id;
                        
                        return (
                          <div key={event.id} className={`border p-4 rounded-2xl shadow-sm relative overflow-hidden ${
                            isDark ? 'theme-selected' : 'bg-surface border-border-default'
                          }`}>
                            <div className="absolute top-0 left-0 w-1.5 h-full accent-btn border-0"></div>
                            
                            <div 
                              className="flex justify-between items-start cursor-pointer pl-1"
                              onClick={() => toggleExpandEvent(event.id)}
                            >
                              <div className="space-y-1.5 flex-1 pr-2">
                                <h4 className="font-bold text-text-primary text-base flex items-center gap-2">
                                  <span className="relative flex h-2.5 w-2.5 shrink-0">
                                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-[color:var(--selected-mark)] opacity-75"></span>
                                    <span className="relative inline-flex rounded-full h-2.5 w-2.5 theme-mark"></span>
                                  </span>
                                  <span>{event.name}</span>
                                </h4>
                                
                                {/* 时间单独成行展示 */}
                                <div className="inline-flex items-center gap-1.5 text-xs text-text-secondary bg-surface-solid border border-border-default px-2.5 py-1 rounded-lg font-medium">
                                  <Clock className="w-3.5 h-3.5 text-[color:var(--action-text)] shrink-0" />
                                  <span>{formatTime(event.startTime)} ~ {formatTime(event.endTime)}</span>
                                </div>

                                {event.description && (
                                  <p className="text-xs text-text-secondary leading-relaxed pt-0.5">{event.description}</p>
                                )}
                              </div>
                              <div className="p-1.5 bg-surface-solid rounded-xl text-text-secondary border border-border-default">
                                {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                              </div>
                            </div>
                            
                            <AnimatePresence>
                              {isExpanded && (
                                <motion.div 
                                  initial={{ height: 0, opacity: 0 }}
                                  animate={{ height: 'auto', opacity: 1 }}
                                  exit={{ height: 0, opacity: 0 }}
                                  className="overflow-hidden"
                                >
                                  <div className="pt-3 mt-3 border-t border-border-default/40 space-y-2.5 pl-1">
                                    {event.stages.length === 0 ? (
                                      <div className="text-xs text-text-secondary font-medium">无具体环节信息</div>
                                    ) : (
                                      event.stages.map(stage => {
                                        const isStageActive = isTimestampInRange(nowTs, stage.startTime, stage.endTime);
                                        return (
                                          <div 
                                            key={stage.id} 
                                            className={`p-3 rounded-xl border ${
                                              isStageActive 
                                                ? 'bg-surface-solid border-border-default shadow-sm' 
                                                : 'bg-surface border-border-default'
                                            } transition-all space-y-1.5`}
                                          >
                                            {/* 环节名称 (第一行) */}
                                            <div className="font-bold text-text-primary text-sm flex items-center gap-1.5">
                                              {isStageActive ? (
                                                <span className={`px-1.5 py-0.5 text-[10px] font-bold rounded-md shrink-0 ${
                                                  isDark ? 'bg-amber-500/25 text-amber-200 border border-amber-400/40' : 'bg-amber-50 text-amber-600 border border-amber-200'
                                                }`}>进行中</span>
                                              ) : (
                                                <span className="w-1.5 h-1.5 bg-border-default rounded-full shrink-0"></span>
                                              )}
                                              <span>{stage.name}</span>
                                            </div>

                                            {/* 环节时间 (第二行) */}
                                            <div className="inline-flex items-center gap-1.5 text-[11px] text-text-secondary bg-surface-solid border border-border-default px-2 py-0.5 rounded-md font-medium">
                                              <Clock className="w-3 h-3 text-[color:var(--action-text)] shrink-0" />
                                              <span>{formatTime(stage.startTime)} ~ {formatTime(stage.endTime)}</span>
                                            </div>

                                            {/* 环节简介 (第三行) */}
                                            {stage.description && (
                                              <p className="text-xs text-text-secondary leading-relaxed pt-0.5">{stage.description}</p>
                                            )}
                                          </div>
                                        );
                                      })
                                    )}
                                  </div>
                                </motion.div>
                              )}
                            </AnimatePresence>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
            )}
            
            {activeTab === 'places' && (
              <div className="space-y-4 pb-12">
                <div className="text-xs text-text-secondary">{(building.places || []).length} 个地点 · {(building.zones || []).length} 个分区</div>
                {placeGroups.length === 0 && <div className="py-8 text-center text-sm text-text-secondary">尚未登记地点</div>}
                {placeGroups.map(group => {
                  const expanded = expandedZones.includes(group.id);
                  return (
                    <section key={group.id} className="rounded-2xl border border-border-default bg-surface-solid overflow-hidden">
                      <button type="button" aria-expanded={expanded} onClick={() => setExpandedZones(current => expanded ? current.filter(id => id !== group.id) : [...current, group.id])} className="w-full flex items-center justify-between gap-3 p-4 text-left hover-fill">
                        <span className="font-bold text-sm text-text-primary">{group.name}</span>
                        <span className="flex items-center gap-2 text-xs text-text-secondary">{group.places.length} 个地点<ChevronDown className={`w-4 h-4 transition-transform ${expanded ? 'rotate-180' : ''}`} /></span>
                      </button>
                      {expanded && (
                        <div className="border-t border-border-default divide-y divide-border-default">
                          {group.places.length === 0 && <p className="p-4 text-xs text-text-secondary">该分区尚未登记地点</p>}
                          {group.places.map(place => {
                            const occupants = activeCharacters.filter(character => character.placeId === place.id);
                            return (
                              <article key={place.id} className="p-4 space-y-2">
                                <div className="flex items-center justify-between gap-2"><h4 className="font-bold text-sm text-text-primary">{place.name}</h4><span className="text-xs text-text-secondary">{place.type}</span></div>
                                {place.description && <p className="text-xs text-text-secondary leading-relaxed">{place.description}</p>}
                                {occupants.length > 0 && <p className="text-xs text-text-secondary">当前角色：{occupants.map(character => character.name).join('、')}</p>}
                              </article>
                            );
                          })}
                        </div>
                      )}
                    </section>
                  );
                })}
              </div>
            )}

            {/* ================= EVENTS TAB ================= */}
            {activeTab === 'events' && (
              <div className="space-y-4 pb-12">
                {!isAddingEvent ? (
                  <>
                    <button 
                      onClick={() => {
                        setEditingEvent(null);
                        setIsAddingEvent(true);
                      }}
                      className="w-full py-3 theme-dashed-btn rounded-2xl font-bold flex items-center justify-center gap-2"
                    >
                      <Plus className="w-5 h-5" /> 添加活动
                    </button>
                    
                    {!(building.events && building.events.length > 0) && (
                      <div className="text-center text-text-secondary text-sm mt-8">暂无建筑活动</div>
                    )}
                    
                    {building.events?.map(event => (
                      <div key={event.id} className="bg-surface-solid rounded-2xl shadow-sm border border-border-default p-4">
                        <div className="flex justify-between items-start">
                          <div className="space-y-1.5 flex-1 pr-2">
                            <h4 className="font-bold text-text-primary text-base flex items-center gap-2">
                              <span>{event.name}</span>
                              {isTimestampInRange(nowTs, event.startTime, event.endTime) && (
                                <span className={`px-1.5 py-0.5 text-[10px] font-bold rounded-md shrink-0 ${
                                  isDark ? 'bg-amber-500/25 text-amber-200 border border-amber-400/40' : 'bg-amber-50 text-amber-600 border border-amber-200'
                                }`}>进行中</span>
                              )}
                            </h4>
                            <div className="inline-flex items-center gap-1.5 text-xs text-text-secondary bg-surface border border-border-default px-2.5 py-1 rounded-lg font-medium">
                              <Clock className="w-3.5 h-3.5 text-text-secondary shrink-0" />
                              <span>{formatTime(event.startTime)} ~ {formatTime(event.endTime)}</span>
                            </div>
                          </div>
                          <button
                            type="button"
                            onClick={() => openEditEvent(event)}
                            className="p-2 text-text-secondary hover-fill rounded-full transition-colors"
                          >
                            <Edit3 className="w-4 h-4" />
                          </button>
                        </div>
                        
                        {event.description && (
                          <p className="text-xs text-text-secondary mt-2.5 leading-relaxed">{event.description}</p>
                        )}
                        
                        {event.stages && event.stages.length > 0 && (
                          <div className="mt-4 pt-3 border-t border-border-default space-y-2.5">
                            <div className="text-xs font-bold text-text-secondary uppercase tracking-widest mb-1">活动环节</div>
                            {event.stages.map((stage) => {
                              const isStageActive = isTimestampInRange(nowTs, stage.startTime, stage.endTime);
                              return (
                                <div key={stage.id} className="p-3 bg-surface border border-border-default rounded-xl space-y-1.5">
                                  <div className="font-bold text-text-primary text-sm flex items-center gap-1.5">
                    {isStageActive ? (
                                      <span className={`px-1.5 py-0.5 text-[10px] font-bold rounded-md shrink-0 ${
                                        isDark ? 'bg-amber-500/25 text-amber-200 border border-amber-400/40' : 'bg-amber-50 text-amber-600 border border-amber-200'
                                      }`}>进行中</span>
                                    ) : (
                                      <span className="w-1.5 h-1.5 bg-border-default rounded-full shrink-0"></span>
                                    )}
                                    <span>{stage.name}</span>
                                  </div>
                                  <div className="inline-flex items-center gap-1.5 text-[11px] text-text-secondary bg-surface-solid border border-border-default px-2 py-0.5 rounded-md font-medium">
                                    <Clock className="w-3 h-3 text-text-secondary shrink-0" />
                                    <span>{formatTime(stage.startTime)} ~ {formatTime(stage.endTime)}</span>
                                  </div>
                                  {stage.description && (
                                    <div className="text-xs text-text-secondary leading-relaxed pt-0.5">{stage.description}</div>
                                  )}
                                </div>
                              );
                            })}
                          </div>
                        )}
                      </div>
                    ))}
                  </>
                ) : (
                  <div className="bg-surface-solid rounded-2xl shadow-sm border border-border-default p-5 space-y-4">
                    <div className="flex justify-between items-center mb-2">
                      <h3 className="font-bold text-text-primary">{editingEvent ? '编辑活动' : '新建活动'}</h3>
                      <button onClick={resetEventForm} className="text-sm font-bold text-text-secondary hover:text-text-primary">取消</button>
                    </div>
                    
                    <input 
                      type="text" placeholder="活动名称..." 
                      value={newEventName} onChange={e => setNewEventName(e.target.value)}
                      className="w-full rounded-lg py-1.5 px-2 text-xs theme-field"
                    />
                    <textarea 
                      placeholder="活动简介..." rows={2}
                      value={newEventDesc} onChange={e => setNewEventDesc(e.target.value)}
                      className="w-full rounded-lg py-1.5 px-2 text-xs theme-field resize-none"
                    />
                    <div className="flex gap-3">
                      <div className="flex-1 w-0">
                        <label className="text-[10px] font-bold text-text-secondary uppercase">开始时间</label>
                        <DateTimePickerModal
                          value={newEventStart}
                          onChange={setNewEventStart}
                          placeholder="选择开始时间"
                          className="w-full bg-surface-solid border border-border-default rounded-lg py-1 px-2 text-[10px] text-text-primary"
                        />
                      </div>
                      <div className="flex-1 w-0">
                        <label className="text-[10px] font-bold text-text-secondary uppercase">结束时间</label>
                        <DateTimePickerModal
                          value={newEventEnd}
                          onChange={setNewEventEnd}
                          placeholder="选择结束时间"
                          className="w-full bg-surface-solid border border-border-default rounded-lg py-1 px-2 text-[10px] text-text-primary"
                        />
                      </div>
                    </div>
                    
                    <div className="pt-4 border-t border-border-default">
                      <h4 className="text-xs font-bold text-text-secondary uppercase mb-3">添加环节</h4>
                      {newEventStages.map((s, i) => (
                        <div key={s.id || i} className="mb-3 p-3 bg-surface rounded-xl text-xs border border-border-default relative">
                          <button onClick={() => setNewEventStages(newEventStages.filter((_, idx) => idx !== i))} className="absolute top-2 right-2 text-rose-500 font-bold">×</button>
                          <div className="font-bold pr-4">{s.name}</div>
                          <div className="text-text-secondary scale-90 origin-left">{formatTime(s.startTime)} ~ {formatTime(s.endTime)}</div>
                          {s.description?.trim() && (
                            <div className="text-text-secondary mt-1 leading-relaxed">{s.description}</div>
                          )}
                        </div>
                      ))}
                      
                      <div className="p-3 border border-dashed border-border-default rounded-xl space-y-3">
                        <input type="text" placeholder="环节名称" value={newStageName} onChange={e => setNewStageName(e.target.value)} className="w-full bg-surface-solid border border-border-default rounded-lg py-1.5 px-2 text-xs" />
                        <input type="text" placeholder="环节简介" value={newStageDesc} onChange={e => setNewStageDesc(e.target.value)} className="w-full bg-surface-solid border border-border-default rounded-lg py-1.5 px-2 text-xs" />
                        <div className="flex gap-2">
                          <div className="flex-1 w-0">
                            <DateTimePickerModal value={newStageStart} onChange={setNewStageStart} placeholder="开始时间" className="w-full theme-field rounded-lg py-1 px-2 text-[10px]" />
                          </div>
                          <div className="flex-1 w-0">
                            <DateTimePickerModal value={newStageEnd} onChange={setNewStageEnd} placeholder="结束时间" className="w-full theme-field rounded-lg py-1 px-2 text-[10px]" />
                          </div>
                        </div>
                        <button onClick={handleAddStage} className="w-full py-1.5 bg-surface text-text-secondary font-bold text-xs rounded-lg hover-fill">
                          确认添加环节
                        </button>
                      </div>
                    </div>
                    
                    <button onClick={handleSubmitEvent} className="w-full py-3 mt-4 accent-btn font-bold rounded-xl shadow-sm">
                      {editingEvent ? '写入修改到输入栏' : '写入酒馆输入栏'}
                    </button>
                  </div>
                )}
              </div>
            )}
            
            {/* ================= CHARACTERS TAB ================= */}
            {activeTab === 'characters' && (
              <div className="space-y-4">
                {activeCharacters.length === 0 ? (
                  <div className="text-center text-text-secondary text-sm mt-8">当前没有角色在这里</div>
                ) : (
                  activeCharacters.map(char => (
                    <Card 
                      key={char.id} 
                      onClick={() => onCharacterClick(char)}
                      className="p-3 flex items-center gap-4 cursor-pointer hover-fill transition-colors relative"
                    >
                      <div className="relative">
                        {char.avatar ? (
                          <CachedImage src={char.avatar} className="w-14 h-14 rounded-full object-cover shrink-0 border-2 border-border-default shadow-sm" alt={char.name}/>
                        ) : (
                          <div className="w-14 h-14 rounded-full bg-surface flex items-center justify-center text-[color:var(--action-text)] font-bold text-lg shrink-0 border-2 border-border-default shadow-sm">
                            {char.name[0]}
                          </div>
                        )}
                      </div>
                      <div className="flex-1 min-w-0 text-left">
                        <div className="flex items-center justify-between mb-1">
                          <span className="font-bold text-text-primary text-base truncate pr-2">{char.name}</span>
                          <div className="flex items-center gap-1 soft-chip px-2 py-0.5 rounded-full">
                            <Heart className="w-3 h-3 fill-current" />
                            <span className="text-xs font-bold">{char.affinity}</span>
                          </div>
                        </div>
                        <div className="text-xs text-text-secondary truncate flex items-center gap-1">
                          <GraduationCap className="w-3.5 h-3.5" />
                          {char.identity || '学生'}{(char as Character & { placeId?: string }).placeId ? ` · ${building.places?.find(place => place.id === (char as Character & { placeId?: string }).placeId)?.name || '具体地点未知'}` : ''}
                        </div>
                      </div>
                    </Card>
                  ))
                )}
              </div>
            )}
            
            {/* ================= RULES TAB ================= */}
            {activeTab === 'rules' && (
              <div className="space-y-4 pb-12">
                {buildingRules.length === 0 ? (
                  <div className="text-center text-text-secondary text-sm mt-8">当前建筑没有特殊规则</div>
                ) : (
                  buildingRules.map(rule => (
                    <RuleCard key={rule.id} rule={rule} buildings={buildings} />
                  ))
                )}
              </div>
            )}
          </motion.div>
        </AnimatePresence>
      </div>
      {activeTab === 'places' && (
        <div className="shrink-0 grid grid-cols-2 gap-3 px-6 py-4 border-t border-border-default bg-surface-solid">
          <button type="button" onClick={() => { resetPlaceForm(); setPlaceEditorMode('add'); }} className="py-3 accent-btn rounded-xl text-sm font-bold flex items-center justify-center gap-2"><Plus className="w-4 h-4" />新增地点</button>
          <button type="button" disabled={!building.places?.length} onClick={() => { resetPlaceForm(); setPlaceEditorMode('edit'); }} className="py-3 border border-border-default rounded-xl text-sm font-bold text-text-primary hover-fill disabled:opacity-50 flex items-center justify-center gap-2"><Edit3 className="w-4 h-4" />编辑地点</button>
        </div>
      )}
      {placeEditorMode !== null && (
        <style>{`.place-select { background-image: none; } .place-select option, .place-select optgroup { background-color: var(--bg-surface-solid); color: var(--text-primary); }`}</style>
      )}
      <CenterModal isOpen={placeEditorMode !== null} onClose={closePlaceEditor} className="w-full max-w-sm max-h-[85%] z-[130]">
        <div className="flex items-center justify-between gap-3 p-5 border-b border-border-default">
          <h3 className="font-bold text-text-primary">{placeEditorMode === 'edit' ? '编辑地点' : '新增地点'}</h3>
          <button type="button" onClick={closePlaceEditor} className="text-sm text-text-secondary hover-fill rounded-lg px-2 py-1">取消</button>
        </div>
        <form onSubmit={submitPlace} className="p-5 space-y-4 overflow-y-auto min-h-0">
          <p className="text-xs text-text-secondary leading-relaxed">提交后将指令写入酒馆输入栏，发送并由 AI 更新 MVU 后，地点列表才会更新。</p>
          {placeEditorMode === 'edit' && (
            <label className="block space-y-2 text-xs text-text-secondary">选择地点
              <div className="relative">
                <select required value={editingPlaceId || ''} onChange={event => selectPlace(event.target.value)} className={placeSelectClass}>
                  <option value="">请选择要编辑的地点</option>
                  {placeGroups.map(group => <optgroup key={group.id} label={group.name}>{group.places.map(place => <option key={place.id} value={place.id}>{place.name}</option>)}</optgroup>)}
                </select>
                <ChevronDown className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-text-secondary" />
              </div>
            </label>
          )}
          <label className="block space-y-2 text-xs text-text-secondary">地点名称
            <input required value={placeName} onChange={event => setPlaceName(event.target.value)} placeholder="地点名称" className="w-full rounded-lg px-3 py-2 text-sm theme-field" />
          </label>
          <label className="block space-y-2 text-xs text-text-secondary">地点类型
            <input value={placeType} onChange={event => setPlaceType(event.target.value)} placeholder="如教室、商店" className="w-full rounded-lg px-3 py-2 text-sm theme-field" />
          </label>
          <label className="block space-y-2 text-xs text-text-secondary">所属分区
            <div className="relative">
              <select value={placeZoneId} onChange={event => setPlaceZoneId(event.target.value)} className={placeSelectClass}>
                <option value="">未分区</option>
                {[...availableZones].sort((a, b) => a.order - b.order).map(zone => <option key={zone.id} value={zone.id}>{zone.name}</option>)}
              </select>
              <ChevronDown className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-text-secondary" />
            </div>
          </label>
          <button type="button" aria-expanded={showZoneForm} onClick={() => setShowZoneForm(value => !value)} className="text-xs font-bold text-text-secondary hover-fill rounded-lg px-2 py-1">{showZoneForm ? '收起新增分区' : '新增楼层或分区'}</button>
          {showZoneForm && (
            <div className="border border-border-default rounded-xl p-3 space-y-3">
              <input aria-label="分区名称" value={zoneName} onChange={event => setZoneName(event.target.value)} placeholder="如一层、二层" className="w-full rounded-lg px-3 py-2 text-sm theme-field" />
              <div className="relative">
                <select aria-label="分区类型" value={zoneType} onChange={event => setZoneType(event.target.value)} className={placeSelectClass}>
                  <option>楼层</option><option>区域</option><option>街区</option><option>场馆</option><option>楼栋</option>
                </select>
                <ChevronDown className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-text-secondary" />
              </div>
              <button type="button" disabled={!zoneName.trim()} onClick={() => {
                const zones = availableZones;
                if (zones.some(zone => zone.name.trim() === zoneName.trim())) {
                  showToast('该分区已存在', 'error');
                  return;
                }
                const zone = { id: zoneName.trim(), name: zoneName.trim(), type: zoneType, order: Math.max(0, ...zones.map(item => item.order)) + 1 };
                setDraftZones(current => [...current, zone]);
                setPlaceZoneId(zone.id);
                setZoneName('');
                setShowZoneForm(false);
              }} className="w-full py-2 border border-border-default rounded-lg text-sm font-bold hover-fill disabled:opacity-50">添加分区</button>
            </div>
          )}
          <label className="block space-y-2 text-xs text-text-secondary">地点描述
            <textarea value={placeDescription} onChange={event => setPlaceDescription(event.target.value)} placeholder="地点描述（选填）" rows={3} className="w-full rounded-lg px-3 py-2 text-sm theme-field resize-none" />
          </label>
          <button type="submit" disabled={!placeName.trim() || (placeEditorMode === 'edit' && !editingPlaceId)} className="w-full py-3 accent-btn rounded-xl text-sm font-bold disabled:opacity-50">{placeEditorMode === 'edit' ? '保存修改' : '添加地点'}</button>
        </form>
      </CenterModal>
    </BottomSheetModal>
  );
};
