import { useCallback, useEffect, useState } from 'react';
import { loadForumPostsFromChat } from '../utils/forumParser';

export const FORUM_INTERACTIONS_STORAGE_KEY = 'campus-app-forum-interactions';
export const MAX_FORUM_FAVORITES = 3;
const PATH = '校园APP.论坛.interactions';
const EVENT = 'campus-forum-interactions-changed';

export interface ForumInteractions {
  liked: string[];
  favorited: string[];
}

function uniqueIds(list: unknown): string[] {
  if (!Array.isArray(list)) return [];
  return [...new Set(list.filter((item): item is string => typeof item === 'string').map(item => item.trim()).filter(Boolean))];
}

function normalize(value: Partial<ForumInteractions> = {}): ForumInteractions {
  return { liked: uniqueIds(value.liked), favorited: uniqueIds(value.favorited).slice(0, MAX_FORUM_FAVORITES) };
}

export function readForumInteractions(): ForumInteractions {
  try {
    const variables = getVariables({ type: 'chat' });
    const stored = _.get(variables, PATH);
    if (stored && typeof stored === 'object') return normalize(stored);
    // Legacy browser data has no chat identity. Claim only IDs present in this chat, once.
    const known = new Set([
      ...(_.get(variables, '校园APP.论坛.posts', []) as Array<{ id: string }>).map(post => post.id),
      ...loadForumPostsFromChat().map(post => post.id),
    ]);
    let next = normalize();
    try {
      const legacy = normalize(JSON.parse(window.localStorage.getItem(FORUM_INTERACTIONS_STORAGE_KEY) || '{}') || {});
      next = { liked: legacy.liked.filter(id => known.has(id)), favorited: legacy.favorited.filter(id => known.has(id)) };
    } catch { /* Invalid legacy storage is ignored. */ }
    updateVariablesWith(current => { _.set(current, PATH, next); return current; }, { type: 'chat' });
    if (next.liked.length || next.favorited.length) {
      try { window.localStorage.removeItem(FORUM_INTERACTIONS_STORAGE_KEY); } catch { /* Chat data remains authoritative. */ }
    }
    return next;
  } catch {
    return normalize();
  }
}

function writeInteractions(next: ForumInteractions) {
  updateVariablesWith(variables => { _.set(variables, PATH, normalize(next)); return variables; }, { type: 'chat' });
  window.dispatchEvent(new CustomEvent(EVENT));
}

function toggleId(list: string[], id: string): string[] {
  return list.includes(id) ? list.filter(item => item !== id) : [...list, id];
}

export function useForumInteractions() {
  const [state, setState] = useState<ForumInteractions>(readForumInteractions);
  useEffect(() => {
    const sync = () => {
      const next = readForumInteractions();
      setState(previous => _.isEqual(previous, next) ? previous : next);
    };
    const subscriptions: EventOnReturn[] = [];
    if (typeof eventOn === 'function') subscriptions.push(eventOn(tavern_events.CHAT_CHANGED, sync));
    const timer = window.setInterval(sync, 800);
    window.addEventListener(EVENT, sync);
    sync();
    return () => {
      subscriptions.forEach(subscription => subscription.stop());
      window.clearInterval(timer);
      window.removeEventListener(EVENT, sync);
    };
  }, []);

  const persist = useCallback((next: ForumInteractions) => {
    try { writeInteractions(next); setState(next); return true; }
    catch (error) { console.warn('[校园论坛] 保存互动失败', error); return false; }
  }, []);
  const isLiked = useCallback((id: string) => state.liked.includes(id), [state.liked]);
  const isFavorited = useCallback((id: string) => state.favorited.includes(id), [state.favorited]);
  const toggleLike = useCallback((id: string) => {
    const latest = readForumInteractions();
    return persist({ ...latest, liked: toggleId(latest.liked, id) });
  }, [persist]);
  const toggleFavorite = useCallback((id: string) => {
    const latest = readForumInteractions();
    if (!latest.favorited.includes(id) && latest.favorited.length >= MAX_FORUM_FAVORITES) return false;
    return persist({ ...latest, favorited: toggleId(latest.favorited, id) });
  }, [persist]);
  return { likedIds: state.liked, favoritedIds: state.favorited, favoriteCount: state.favorited.length, favoriteLimit: MAX_FORUM_FAVORITES, isLiked, isFavorited, toggleLike, toggleFavorite };
}
