import { useEffect, useState } from 'react';
import { PhoneSimulator } from '../状态栏/src/components/PhoneSimulator';
import { ensureMvuStatDataInitialized } from '../状态栏/src/hooks/useMvuData';
import { CustomStartForm } from './constants';
import { CustomStartScreen } from './CustomStartScreen';
import { MainMenuScreen } from './MainMenuScreen';

interface OpeningFlowProps {
  onEnroll: (form: CustomStartForm) => void | Promise<void>;
}

export function OpeningFlow({ onEnroll }: OpeningFlowProps) {
  const [step, setStep] = useState<'menu' | 'custom' | 'workshop'>('menu');

  useEffect(() => {
    void ensureMvuStatDataInitialized();
  }, []);

  if (step === 'custom') {
    return (
      <CustomStartScreen
        onBack={() => setStep('menu')}
        onConfirm={onEnroll}
      />
    );
  }

  if (step === 'workshop') {
    return (
      <PhoneSimulator
        initialTab="settings"
        hideHomeNav
        initialWorkshopModule="enrollment"
        onCloseToMenu={() => setStep('menu')}
      />
    );
  }

  return <MainMenuScreen onStart={() => setStep('custom')} onOpenWorkshop={() => setStep('workshop')} />;
}
