import { Minus, Plus } from 'lucide-react';
import { useEffect, useState } from 'react';

interface SizeStepperProps {
  label: string;
  value: number;
  min?: number;
  max?: number;
  onChange: (next: number) => void;
}

function clampSize(value: number, min: number, max: number) {
  if (!Number.isFinite(value)) return min;
  return Math.min(max, Math.max(min, Math.round(value)));
}

export function SizeStepper({ label, value, min = 1, max = 6, onChange }: SizeStepperProps) {
  const [draft, setDraft] = useState(String(value));
  const [focused, setFocused] = useState(false);
  const canDecrease = value > min;
  const canIncrease = value < max;

  useEffect(() => {
    if (!focused) setDraft(String(value));
  }, [value, focused]);

  const commit = (raw: string) => {
    const parsed = parseInt(raw, 10);
    const next = clampSize(Number.isNaN(parsed) ? min : parsed, min, max);
    setDraft(String(next));
    if (next !== value) onChange(next);
  };

  const step = (delta: number) => {
    const next = clampSize(value + delta, min, max);
    setDraft(String(next));
    if (next !== value) onChange(next);
  };

  return (
    <div className="flex-1 min-w-0">
      <label className="text-xs font-bold text-text-secondary mb-2 block">{label}</label>
      <div
        className="flex items-stretch rounded-xl overflow-hidden theme-field p-0"
        data-no-drag-scroll
        onPointerDown={event => event.stopPropagation()}
      >
        <button
          type="button"
          onClick={() => step(-1)}
          disabled={!canDecrease}
          className="w-11 shrink-0 flex items-center justify-center text-text-secondary hover-fill transition-colors disabled:opacity-35 disabled:pointer-events-none"
          aria-label="减小"
        >
          <Minus className="w-4 h-4" />
        </button>
        <input
          type="text"
          inputMode="numeric"
          pattern="[0-9]*"
          value={focused ? draft : String(value)}
          onFocus={() => {
            setFocused(true);
            setDraft(String(value));
          }}
          onBlur={() => {
            commit(draft);
            setFocused(false);
          }}
          onChange={event => {
            const nextDraft = event.target.value.replace(/[^\d]/g, '').slice(0, 2);
            setDraft(nextDraft);
            if (nextDraft === '') return;
            const parsed = parseInt(nextDraft, 10);
            if (!Number.isNaN(parsed) && parsed >= min && parsed <= max) {
              onChange(parsed);
            }
          }}
          className="flex-1 min-w-0 bg-transparent text-center font-mono text-base text-text-primary outline-none border-x border-border-default py-3"
        />
        <button
          type="button"
          onClick={() => step(1)}
          disabled={!canIncrease}
          className="w-11 shrink-0 flex items-center justify-center text-text-secondary hover-fill transition-colors disabled:opacity-35 disabled:pointer-events-none"
          aria-label="增大"
        >
          <Plus className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}
