export type PhoneCloseMode = 'button' | 'outside';

const STORAGE_KEY = 'campus-app-close-mode';

function getStorage(): Storage | null {
  try {
    const parent = window.parent && window.parent !== window ? window.parent : window;
    return parent.localStorage;
  } catch {
    try {
      return window.localStorage;
    } catch {
      return null;
    }
  }
}

export function loadPhoneCloseMode(): PhoneCloseMode {
  try {
    return getStorage()?.getItem(STORAGE_KEY) === 'outside' ? 'outside' : 'button';
  } catch {
    return 'button';
  }
}

export function savePhoneCloseMode(mode: PhoneCloseMode) {
  try {
    getStorage()?.setItem(STORAGE_KEY, mode);
  } catch {
    // ignore
  }
}
