import { useEffect, useMemo, useState } from 'react';
import { Character, ChatGroup, ChatThread, Player } from '../types';
import { ChatParseContext, loadChatThreadsFromChat } from '../utils/chatParser';
import { useMvuSnapshot } from './useMvuData';

export function useChatThreads(context?: ChatParseContext): ChatThread[] {
  const mvuData = useMvuSnapshot();
  const effectiveContext = useMemo(() => context ?? {
    playerNames: [mvuData.玩家?.姓名 || '', '{{user}}'].filter(Boolean),
    characters: Object.values(mvuData.角色 || {}).map(character => ({
      name: character.姓名,
      nickname: character.网名,
      isFriend: character.好友位 === true,
    })),
    groups: Object.entries(mvuData.聊天群组 || {}).map(([name, group]) => ({
      name: group.群名 || name,
      memberNames: group.成员,
    })),
  }, [context, mvuData.玩家, mvuData.角色, mvuData.聊天群组]);
  const [threads, setThreads] = useState<ChatThread[]>(() => loadChatThreadsFromChat(mvuData.时间, effectiveContext));

  useEffect(() => {
    let cancelled = false;
    const sync = () => {
      const next = loadChatThreadsFromChat(mvuData.时间, effectiveContext);
      if (cancelled) return;
      setThreads(prev => (_.isEqual(prev, next) ? prev : next));
    };

    sync();
    const timer = window.setInterval(sync, 800);
    try {
      eventOn(tavern_events.MESSAGE_RECEIVED, sync);
      eventOn(tavern_events.MESSAGE_UPDATED, sync);
      eventOn(tavern_events.CHAT_CHANGED, sync);
    } catch {
      // ignore
    }

    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [mvuData.时间, effectiveContext]);

  return threads;
}

export function buildChatParseContext(player: Player, characters: Character[], groups: ChatGroup[]): ChatParseContext {
  return {
    playerNames: [player.name, '{{user}}'].filter(Boolean),
    characters: characters.map(character => ({
      name: character.name,
      nickname: character.nickname,
      isFriend: character.isFriend === true,
    })),
    groups: groups.map(group => ({
      name: group.name,
      memberNames: group.memberNames,
    })),
  };
}
