import { CachedImage, CachedMotionImage } from '../shared/CachedImage';
import { AnimatePresence, motion } from 'framer-motion';
import { ArrowDownToLine, ChevronLeft, ChevronRight, Image, UserRound, X } from 'lucide-react';
import { useEffect, useMemo, useState, type TouchEvent } from 'react';
import { presetCharacterImages, type PresetCharacterImages } from '../../utils/presetCharacterImages';
import { loadRemoteImageManifest } from '../../utils/remoteImageManifest';

interface GalleryScreenProps {
  onClose: () => void;
}

type GalleryFilter = '全部' | '立绘' | '头像';
type GalleryAsset = { src: string; label: string; kind: '立绘' | '头像' };

type GalleryEntry = {
  name: string;
  avatar: string;
  portraits: { src: string; outfit: string }[];
};

function buildEntries(manifest: Record<string, PresetCharacterImages>): GalleryEntry[] {
  return Object.entries(manifest).map(([name, images]) => ({
    name,
    avatar: images.avatar,
    portraits: images.portraits.map((src, index) => ({
      src,
      outfit: images.portraitLabels[index] || '立绘',
    })),
  }));
}

function getAssets(character: ReturnType<typeof buildEntries>[number], filter: GalleryFilter): GalleryAsset[] {
  return [
    ...(filter !== '立绘' ? [{ src: character.avatar, label: '头像', kind: '头像' as const }] : []),
    ...(filter !== '头像' ? character.portraits.map(item => ({ src: item.src, label: item.outfit, kind: '立绘' as const })) : []),
  ];
}

export function GalleryScreen({ onClose }: GalleryScreenProps) {
  const [manifest, setManifest] = useState<Record<string, PresetCharacterImages>>(() => ({ ...presetCharacterImages }));
  const entries = useMemo(() => buildEntries(manifest), [manifest]);
  useEffect(() => {
    let active = true;
    void loadRemoteImageManifest().then(next => {
      if (active) setManifest(next);
    });
    return () => {
      active = false;
    };
  }, []);
  const [filter, setFilter] = useState<GalleryFilter>('全部');
  const [selectedCharacter, setSelectedCharacter] = useState<number | null>(null);
  const [previewIndex, setPreviewIndex] = useState<number | null>(null);
  const [fullscreenIndex, setFullscreenIndex] = useState<number | null>(null);
  const [touchStartX, setTouchStartX] = useState<number | null>(null);

  const character = selectedCharacter == null ? null : entries[selectedCharacter];
  const assets = character ? getAssets(character, filter) : [];
  const preview = previewIndex == null ? null : assets[previewIndex];
  const fullscreenAsset = fullscreenIndex == null ? null : assets[fullscreenIndex];

  const selectFilter = (nextFilter: GalleryFilter) => {
    setFilter(nextFilter);
    setPreviewIndex(0);
    setFullscreenIndex(null);
  };

  const openCharacter = (index: number) => {
    setSelectedCharacter(index);
    setPreviewIndex(0);
  };

  const closeCharacter = () => {
    setSelectedCharacter(null);
    setPreviewIndex(null);
    setFullscreenIndex(null);
  };

  const moveFullscreen = (direction: number) => {
    if (fullscreenIndex == null || !assets.length) return;
    setFullscreenIndex((fullscreenIndex + direction + assets.length) % assets.length);
  };

  const downloadAsset = () => {
    if (!fullscreenAsset) return;
    const link = document.createElement('a');
    link.href = fullscreenAsset.src;
    link.download = `${character?.name || '角色'}-${fullscreenAsset.label}.png`;
    link.click();
  };

  const handleTouchEnd = (event: TouchEvent) => {
    if (touchStartX == null) return;
    const distance = event.changedTouches[0].clientX - touchStartX;
    if (Math.abs(distance) > 45) moveFullscreen(distance > 0 ? -1 : 1);
    setTouchStartX(null);
  };

  return (
    <motion.div
      className={`absolute inset-0 ${fullscreenAsset ? 'z-[100]' : 'z-20'} flex flex-col`}
      style={{ background: 'var(--bg-app)' }}
      initial={{ x: '100%' }}
      animate={{ x: 0 }}
      exit={{ x: '100%' }}
      transition={{ type: 'spring', stiffness: 280, damping: 30 }}
    >
      <header className="relative z-10 flex items-center justify-between border-b border-border-default/40 px-4 pb-3 pt-12">
        <div className="flex items-center gap-2">
          <button onClick={selectedCharacter == null ? onClose : closeCharacter} aria-label="返回" className="rounded-full p-2 text-text-primary hover:bg-black/5 theme-dark:hover:bg-white/10">
            <ChevronLeft className="h-5 w-5" />
          </button>
          <div>
            <h1 className="text-lg font-bold text-text-primary">{character?.name || '角色图库'}</h1>
            {character && <p className="text-[11px] text-text-secondary">头像与立绘</p>}
          </div>
        </div>
        {selectedCharacter != null && (
          <div className="flex rounded-lg border border-border-default/60 p-0.5" role="tablist" aria-label="图片类型">
            {(['全部', '立绘', '头像'] as GalleryFilter[]).map(item => (
              <button key={item} role="tab" aria-selected={filter === item} onClick={() => selectFilter(item)} className={`rounded-md px-2.5 py-1.5 text-xs transition-colors ${filter === item ? 'theme-selected' : 'text-text-secondary'}`}>
                {item}
              </button>
            ))}
          </div>
        )}
      </header>

      {selectedCharacter == null ? (
        <main className="min-h-0 flex-1 overflow-x-hidden overflow-y-auto hide-scrollbar px-4 pb-6 pt-4">
            <h2 className="text-xs font-semibold uppercase tracking-widest text-text-secondary">角色列表</h2>
          <div className="grid grid-cols-2 gap-3">
            {entries.map((item, index) => (
              <motion.button key={item.name} whileTap={{ scale: 0.97 }} onClick={() => openCharacter(index)} className="flex items-center gap-3 rounded-xl border border-border-default/60 bg-surface p-3 text-left shadow-sm transition-colors hover:border-rose-300">
                <CachedImage src={item.avatar} alt="" className="h-14 w-14 shrink-0 rounded-full border border-border-default object-cover" />
                <span className="min-w-0"><strong className="block truncate text-sm text-text-primary">{item.name}</strong><span className="mt-1 block text-[10px] text-text-secondary">{item.portraits.length + 1} 张图片</span></span>
              </motion.button>
            ))}
          </div>
        </main>
      ) : (
        <main className="min-h-0 flex-1 overflow-x-hidden overflow-y-auto hide-scrollbar px-4 pb-6 pt-3">
          <div className="relative mb-3 flex h-8 items-center justify-center">
            <CachedImage src={character.avatar} alt="" className="h-8 w-8 rounded-full border border-border-default object-cover" />
            <span className="ml-2 text-sm font-semibold text-text-primary">{character.name}</span>
          </div>
          <div className="relative flex h-[min(38vh,300px)] min-h-48 items-center justify-center overflow-hidden rounded-xl border border-border-default/50 bg-black/[0.035] theme-dark:bg-white/[0.035]">
            <AnimatePresence mode="wait">
              {preview && <motion.button key={preview.src} onClick={() => setFullscreenIndex(previewIndex)} className="h-full w-full cursor-zoom-in" initial={{ opacity: 0, scale: 0.97, x: 12 }} animate={{ opacity: 1, scale: 1, x: 0 }} exit={{ opacity: 0, scale: 0.98, x: -12 }} transition={{ duration: 0.2 }} aria-label="放大查看图片"><CachedImage src={preview.src} alt={`${character.name} ${preview.label}`} className={`h-full w-full ${preview.kind === '头像' ? 'object-contain p-5' : 'object-contain'}`} /></motion.button>}
            </AnimatePresence>
            {!preview && <p className="text-xs text-text-secondary">选择下方图片预览</p>}
            {preview && <span className="pointer-events-none absolute bottom-2 left-2 rounded-md bg-black/55 px-2 py-1 text-[10px] text-white">{preview.label}</span>}
          </div>
          <div className="mb-2 mt-4 flex items-center justify-between"><h3 className="text-xs font-semibold text-text-primary">{filter === '头像' ? '头像' : filter === '立绘' ? '立绘' : '全部图片'}</h3></div>
          <div className="grid grid-cols-3 gap-2.5">
            {assets.map((asset, index) => (
              <button key={asset.src} onClick={() => setPreviewIndex(index)} aria-label={`${character.name} ${asset.label}`} aria-pressed={preview?.src === asset.src} className={`group relative overflow-hidden rounded-lg border transition-all ${preview?.src === asset.src ? 'border-rose-400 ring-2 ring-rose-400/25' : 'border-border-default/60 hover:border-rose-300'}`}>
                <div className={`h-24 bg-black/[0.035] theme-dark:bg-white/[0.035] ${asset.kind === '头像' ? 'p-3' : ''}`}><CachedImage src={asset.src} alt="" loading="lazy" className={`h-full w-full transition-transform duration-200 group-hover:scale-[1.03] ${asset.kind === '头像' ? 'rounded-md object-contain' : 'object-cover object-top'}`} /></div>
                <div className="flex items-center justify-center gap-1 bg-surface-solid px-1 py-1.5 text-[10px] text-text-secondary"><span>{asset.kind === '头像' ? <UserRound className="h-3 w-3" /> : <Image className="h-3 w-3" />}</span><span className="truncate">{asset.label}</span></div>
              </button>
            ))}
          </div>
        </main>
      )}

      <AnimatePresence>
        {fullscreenAsset && (
          <motion.div className="absolute inset-0 z-40 flex flex-col bg-black" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <div className="flex items-center justify-between px-4 pb-3 pt-12 text-white">
              <button onClick={() => setFullscreenIndex(null)} aria-label="关闭全屏预览" className="rounded-full bg-white/10 p-2"><X className="h-5 w-5" /></button>
              <span className="text-xs">{character?.name} · {fullscreenAsset.label}</span>
              <button onClick={downloadAsset} aria-label="下载图片" className="rounded-full bg-white/10 p-2"><ArrowDownToLine className="h-5 w-5" /></button>
            </div>
            <div className="relative flex min-h-0 flex-1 items-center justify-center" onTouchStart={event => setTouchStartX(event.touches[0].clientX)} onTouchEnd={handleTouchEnd}>
              <button onClick={() => moveFullscreen(-1)} aria-label="上一张" className="absolute left-3 z-10 rounded-full bg-white/10 p-2 text-white"><ChevronLeft className="h-5 w-5" /></button>
              <AnimatePresence mode="wait">
                <CachedMotionImage key={fullscreenAsset.src} src={fullscreenAsset.src} alt={`${character?.name} ${fullscreenAsset.label}`} className="max-h-full max-w-full select-none object-contain" initial={{ opacity: 0, x: 24 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -24 }} transition={{ duration: 0.18 }} draggable={false} />
              </AnimatePresence>
              <button onClick={() => moveFullscreen(1)} aria-label="下一张" className="absolute right-3 z-10 rounded-full bg-white/10 p-2 text-white"><ChevronRight className="h-5 w-5" /></button>
            </div>
            <p className="pb-7 pt-3 text-center text-[10px] text-white/60">左右滑动切换图片</p>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}
