import React, { useMemo, useState, useEffect } from 'react';
import { FullScreenModal } from '../ui/Modal';
import { ForumMedia, ForumPost, ForumReply } from '../../types';
import {
  Heart,
  MessageSquare,
  Star,
  ChevronLeft,
  User,
  Clock,
  RefreshCw,
  Trash2,
  History,
  X,
  Bell,
  Search,
  Settings,
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';
import { MAX_FORUM_FAVORITES, useForumInteractions } from '../../hooks/useForumInteractions';
import { useForumPosts } from '../../hooks/useForumPosts';
import { useMvuSnapshot } from '../../hooks/useMvuData';
import { formatForumRelativeTime, mvuTimeToTimestamp } from '../../utils/forumParser';
import { showToast } from '../ui/Toast';
import { forumErrorMessage, clearForumData, readForumState, saveForumState } from '../../utils/forumGeneration';
import { resolveForumBoardName } from '../../utils/forumCategories';
import { useForumGeneration } from '../../hooks/useForumGeneration';

const formatTime = (ts: number, nowTs: number) => formatForumRelativeTime(ts, nowTs);

function displayCount(base: number, active: boolean) {
  return Math.max(0, base + (active ? 1 : 0));
}

const MediaPreview: React.FC<{ media?: ForumMedia[]; compact?: boolean }> = ({ media, compact = false }) =>
  !media?.length ? null : (
    <div className={`mt-3 grid gap-2 ${compact ? '' : 'px-1'}`}>
      {media.map((item, index) => (
        <div
          key={`${item.description}-${index}`}
          className={`flex min-h-28 w-full items-center justify-center rounded-xl border border-border-default/70 bg-surface/65 px-5 py-4 text-center shadow-inner ${compact ? 'min-h-24' : ''}`}
        >
          <span className="max-w-xl break-words text-xs leading-relaxed text-text-secondary">{item.description}</span>
        </div>
      ))}
    </div>
  );

const PostItem: React.FC<{
  post: ForumPost;
  nowTs: number;
  liked: boolean;
  favorited: boolean;
  onClick: () => void;
  onToggleLike: () => void;
  onToggleFavorite: () => void;
}> = ({ post, nowTs, liked, favorited, onClick, onToggleLike, onToggleFavorite }) => {
  return (
    <div
      className="bg-surface-solid rounded-2xl p-4 mb-3 shadow-sm border border-border-default cursor-pointer hover-fill active:scale-[0.98] transition-transform"
      onClick={onClick}
    >
      <div className="flex items-center gap-3 mb-2">
        <div className="w-8 h-8 rounded-full bg-indigo-50 flex items-center justify-center overflow-hidden shrink-0">
          {post.authorAvatar ? (
            <img src={post.authorAvatar} alt={post.authorName} className="w-full h-full object-cover" />
          ) : (
            <User className="w-4 h-4 text-indigo-400" />
          )}
        </div>
        <div className="flex-1 min-w-0">
          <div className="text-sm font-medium text-text-primary truncate">{post.authorName}</div>
          <div className="flex items-center gap-1 text-[10px] text-text-secondary">
            <Clock className="w-3 h-3" />
            {formatTime(post.timestamp, nowTs)}
            {post.board ? <span className="ml-1 px-1.5 py-0.5 rounded-full soft-chip">{post.board}</span> : null}
          </div>
        </div>
      </div>
      <h3 className="text-base font-bold text-text-primary mb-1 line-clamp-2">{post.title}</h3>
      <p className="text-sm text-text-secondary mb-3 line-clamp-3 leading-relaxed">{post.content}</p>
      <MediaPreview media={post.media} compact />

      <div className="flex items-center justify-between text-text-secondary">
        <div className="flex items-center gap-4">
          <button
            type="button"
            onClick={event => {
              event.stopPropagation();
              onToggleLike();
            }}
            className={`flex items-center gap-1 text-xs ${liked ? 'text-[color:var(--action-text)]' : 'text-text-secondary'}`}
          >
            <Heart className={`w-4 h-4 ${liked ? 'fill-[color:var(--action-text)]' : ''}`} />
            <span>{displayCount(post.likes, liked)}</span>
          </button>
          <div className="flex items-center gap-1 text-xs">
            <MessageSquare className="w-4 h-4" />
            <span>{post.replies.length}</span>
          </div>
        </div>
        <button
          type="button"
          onClick={event => {
            event.stopPropagation();
            onToggleFavorite();
          }}
          className={`flex items-center gap-1 text-xs ${favorited ? 'text-amber-500' : 'text-text-secondary'}`}
        >
          <Star className={`w-4 h-4 ${favorited ? 'fill-amber-400' : ''}`} />
          <span>{displayCount(post.favorites, favorited)}</span>
        </button>
      </div>
    </div>
  );
};

const ReplyItem: React.FC<{ reply: ForumReply; isNested?: boolean; nowTs: number }> = ({
  reply,
  isNested = false,
  nowTs,
}) => {
  return (
    <div className={`flex gap-3 ${isNested ? 'mt-3 pl-11' : 'border-b border-border-default py-4'}`}>
      {!isNested && (
        <div className="w-8 h-8 rounded-full bg-surface flex items-center justify-center overflow-hidden shrink-0">
          {reply.authorAvatar ? (
            <img src={reply.authorAvatar} alt={reply.authorName} className="w-full h-full object-cover" />
          ) : (
            <User className="w-4 h-4 text-text-secondary" />
          )}
        </div>
      )}
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between mb-1">
          <div className="flex items-center gap-2">
            {isNested && (
              <div className="w-5 h-5 rounded-full bg-surface flex items-center justify-center overflow-hidden shrink-0">
                {reply.authorAvatar ? (
                  <img src={reply.authorAvatar} alt={reply.authorName} className="w-full h-full object-cover" />
                ) : (
                  <User className="w-3 h-3 text-text-secondary" />
                )}
              </div>
            )}
            <span className="text-sm font-medium text-text-primary">{reply.authorName}</span>
          </div>
          <div className="flex items-center gap-1 text-xs text-text-secondary">
            <Heart className="w-3 h-3" />
            <span>{reply.likes}</span>
          </div>
        </div>
        <p className="text-sm text-text-secondary leading-relaxed mb-1">{reply.content}</p>
        <MediaPreview media={reply.media} compact />
        <div className="text-[10px] text-text-secondary">{formatTime(reply.timestamp, nowTs)}</div>

        {/* Nested replies */}
        {reply.replies && reply.replies.length > 0 && (
          <div className="mt-2 bg-surface rounded-xl p-3 border border-border-default">
            {reply.replies.map(nestedReply => (
              <div key={nestedReply.id} className="mb-2 last:mb-0">
                <p className="text-xs leading-relaxed break-words">
                  <span className="font-medium text-text-primary">{nestedReply.authorName}：</span>
                  <span className="text-text-secondary">{nestedReply.content}</span>
                </p>
                <MediaPreview media={nestedReply.media} compact />
                <div className="flex items-center justify-between mt-0.5">
                  <span className="text-[10px] text-text-secondary">{formatTime(nestedReply.timestamp, nowTs)}</span>
                  <div className="flex items-center gap-1 text-[10px] text-text-secondary">
                    <Heart className="w-3 h-3" />
                    <span>{nestedReply.likes}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export const ForumScreen: React.FC<{
  onClose: () => void;
  onOpenSettings?: (section?: 'forum' | 'forum-categories') => void;
  notificationRequest?: number;
}> = ({ onClose, onOpenSettings, notificationRequest }) => {
  const rawPosts = useForumPosts();
  const mvuData = useMvuSnapshot();
  const nowTs = mvuTimeToTimestamp(mvuData.时间);
  const { isLiked, isFavorited, toggleLike, toggleFavorite, favoritedIds } = useForumInteractions();
  const handleToggleFavorite = (id: string) => {
    const ok = toggleFavorite(id);
    if (!ok) {
      showToast(`最多只能收藏 ${MAX_FORUM_FAVORITES} 个帖子`, 'info', 1800);
    }
  };
  const { busy: generating, state: generationState, config: generationConfig, generate, cancel } = useForumGeneration();
  const posts = useMemo(
    () => rawPosts.map(post => ({ ...post, board: resolveForumBoardName(post.board, generationConfig.categories) })),
    [rawPosts, generationConfig.categories],
  );
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [showFavorites, setShowFavorites] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [selectedRecordId, setSelectedRecordId] = useState<string | null>(null);
  const [showTools, setShowTools] = useState(false);
  const [confirmClear, setConfirmClear] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeBoard, setActiveBoard] = useState('全部');
  useEffect(() => {
    if (!notificationRequest) return;
    const state = readForumState();
    if (state.unreadPostIds?.length) saveForumState({ ...state, unreadPostIds: [] });
  }, [notificationRequest]);
  const selectedPost = useMemo(() => posts.find(post => post.id === selectedId) || null, [posts, selectedId]);
  const selectedRecord = useMemo(
    () => generationState.records?.find(record => record.id === selectedRecordId) || null,
    [generationState.records, selectedRecordId],
  );
  const handleGenerate = async () => {
    if (generating) {
      cancel();
      return;
    }
    try {
      await generate();
      showToast('论坛内容已更新', 'success');
    } catch (error) {
      showToast(forumErrorMessage(error), 'error');
    }
  };

  const handleOpenPost = (id: string) => {
    const remaining = (generationState.unreadPostIds || []).filter(unreadId => unreadId !== id);
    saveForumState({ ...readForumState(), unreadPostIds: remaining });
    setSelectedId(id);
  };
  const handleClear = () => {
    clearForumData();
    setConfirmClear(false);
    setShowTools(false);
    setSelectedId(null);
    showToast('当前聊天论坛数据已清空', 'success');
  };
  const favoritePosts = useMemo(
    () => posts.filter(post => favoritedIds.includes(post.id)).sort((a, b) => b.timestamp - a.timestamp),
    [posts, favoritedIds],
  );
  const boards = useMemo(
    () =>
      [
        ...new Set([
          ...generationConfig.categories.map(category => category.name),
          ...posts.map(post => post.board || '综合'),
        ]),
      ].sort((a, b) => a.localeCompare(b, 'zh-CN')),
    [generationConfig.categories, posts],
  );
  const selectedBoardName = resolveForumBoardName(activeBoard, generationConfig.categories);
  const selectedBoard = activeBoard === '全部' || !boards.includes(selectedBoardName) ? '全部' : selectedBoardName;
  const filteredPosts = useMemo(() => {
    const query = searchQuery.trim().toLocaleLowerCase();
    return posts.filter(post => {
      const board = post.board?.trim() || '综合';
      const matchesBoard = selectedBoard === '全部' || board === selectedBoard;
      const matchesQuery =
        !query ||
        [post.title, post.content, post.authorName, board].some(value => value.toLocaleLowerCase().includes(query));
      return matchesBoard && matchesQuery;
    });
  }, [posts, selectedBoard, searchQuery]);
  const dragProps = useDraggableScroll<HTMLDivElement>();
  const detailDragProps = useDraggableScroll<HTMLDivElement>();
  const favoriteDragProps = useDraggableScroll<HTMLDivElement>();
  const boardDragProps = useDraggableScroll<HTMLDivElement>();

  return (
    <FullScreenModal isOpen={true} className="z-20">
      <div className="flex items-center justify-between px-4 py-4 sticky top-0 z-10 border-b border-border-default/30">
        <h1 className="min-w-0 flex-1 text-base font-bold text-text-primary flex items-center gap-2">
          <MessageSquare className="w-5 h-5 text-[color:var(--action-text)] shrink-0" />
          <span className="truncate">校园论坛</span>
        </h1>
        <div className="flex items-center gap-1 shrink-0">
          <button
            type="button"
            onClick={() => void handleGenerate()}
            title={generating ? '取消论坛生成' : '根据当前剧情生成论坛内容'}
            className="h-8 px-3 rounded-full bg-surface-solid border border-border-default text-xs font-bold text-text-secondary flex items-center gap-1 hover-fill"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${generating ? 'animate-spin' : ''}`} />
            {generating ? '取消' : '生成'}
          </button>
          <button
            type="button"
            onClick={() => setShowTools(true)}
            title="更多论坛功能"
            className="relative h-8 w-9 rounded-full border border-border-default bg-surface-solid text-sm font-bold tracking-widest text-text-secondary"
          >
            •••
            {(generationState.unreadPostIds?.length || 0) > 0 && (
              <span className="absolute -right-1 -top-1 min-w-4 rounded-full bg-rose-500 px-1 text-center text-[9px] leading-4 text-white">
                {generationState.unreadPostIds?.length}
              </span>
            )}
          </button>
          <button
            type="button"
            onClick={onClose}
            title="返回"
            aria-label="返回论坛上一页"
            className="p-2 glass rounded-full hover-fill transition-colors shadow-sm border border-border-default shrink-0"
          >
            <ChevronLeft className="w-5 h-5 text-text-primary" />
          </button>
        </div>
      </div>

      <div
        className="flex-1 min-h-0 overflow-y-auto px-4 py-3 pb-6 hide-scrollbar relative select-none cursor-grab active:cursor-grabbing touch-none"
        {...dragProps}
        ref={dragProps.ref}
      >
        <div
          data-no-drag-scroll
          className="mb-3 flex items-center gap-2 rounded-xl border border-border-default bg-surface-solid px-3 py-2.5 text-text-secondary"
        >
          <Search className="h-4 w-4 shrink-0" />
          <input
            type="search"
            value={searchQuery}
            onChange={event => setSearchQuery(event.target.value)}
            placeholder="搜索帖子、作者或板块"
            aria-label="搜索论坛帖子"
            className="min-w-0 flex-1 bg-transparent text-sm text-text-primary outline-none placeholder:text-text-secondary"
          />
          {searchQuery && (
            <button
              type="button"
              onClick={() => setSearchQuery('')}
              aria-label="清除搜索"
              className="text-xs text-text-secondary"
            >
              清除
            </button>
          )}
        </div>
        <div
          data-no-drag-scroll
          className="mb-3 flex gap-2 overflow-x-auto hide-scrollbar cursor-grab active:cursor-grabbing select-none touch-pan-x"
          role="tablist"
          aria-label="论坛板块"
          {...boardDragProps}
          ref={boardDragProps.ref}
        >
          {['全部', ...boards].map(board => (
            <button
              key={board}
              type="button"
              role="tab"
              aria-selected={selectedBoard === board}
              onClick={() => setActiveBoard(board)}
              className={`shrink-0 rounded-full border px-3 py-1.5 text-xs font-semibold ${selectedBoard === board ? 'accent-btn' : 'border-border-default bg-surface-solid text-text-secondary'}`}
            >
              {board}
            </button>
          ))}
        </div>
        {filteredPosts.map(post => (
          <div key={post.id} className="relative">
            {(generationState.unreadPostIds || []).includes(post.id) && (
              <span className="absolute right-2 top-2 z-10 rounded-full bg-rose-500 px-2 py-0.5 text-[9px] font-bold text-white">
                新回复
              </span>
            )}
            <PostItem
              post={post}
              nowTs={nowTs}
              liked={isLiked(post.id)}
              favorited={isFavorited(post.id)}
              onClick={() => handleOpenPost(post.id)}
              onToggleLike={() => toggleLike(post.id)}
              onToggleFavorite={() => handleToggleFavorite(post.id)}
            />
          </div>
        ))}
        {filteredPosts.length === 0 && (
          <div className="text-center text-text-secondary mt-20 text-sm px-6 leading-relaxed">
            {posts.length === 0 ? '暂无校园论坛帖子。' : '没有找到符合条件的帖子。'}
            <br />
            回复完成后可自动生成讨论，也可以点击右上角“生成”。
          </div>
        )}
      </div>

      <AnimatePresence>
        {showTools && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 z-50 flex items-end bg-black/30 p-4"
            onClick={() => setShowTools(false)}
          >
            <section
              className="w-full rounded-2xl border border-border-default bg-surface-solid p-4 shadow-xl"
              onClick={event => event.stopPropagation()}
            >
              <header className="mb-3 flex items-center justify-between">
                <h2 className="font-bold text-text-primary">更多功能</h2>
                <button
                  type="button"
                  aria-label="关闭"
                  onClick={() => setShowTools(false)}
                  className="p-1 text-text-secondary"
                >
                  <X className="h-4 w-4" />
                </button>
              </header>
              <div className="mb-3 grid grid-cols-2 gap-2">
                <button
                  type="button"
                  onClick={() => {
                    setShowFavorites(true);
                    setShowTools(false);
                  }}
                  className="flex items-center justify-center gap-2 rounded-xl border border-border-default py-2.5 text-xs font-semibold text-text-secondary"
                >
                  <Star className="h-3.5 w-3.5 text-amber-500" />
                  我的收藏 {favoritePosts.length}/{MAX_FORUM_FAVORITES}
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setShowHistory(true);
                    setShowTools(false);
                  }}
                  className="flex items-center justify-center gap-2 rounded-xl border border-border-default py-2.5 text-xs font-semibold text-text-secondary"
                >
                  <History className="h-3.5 w-3.5" />
                  生成记录
                </button>
                {onOpenSettings && (
                  <>
                    <button
                      type="button"
                      onClick={() => {
                        setShowTools(false);
                        onOpenSettings('forum');
                      }}
                      className="col-span-2 flex items-center justify-center gap-2 rounded-xl border border-border-default py-2.5 text-xs font-semibold text-text-secondary"
                    >
                      <Settings className="h-3.5 w-3.5" />
                      论坛生成设置
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        setShowTools(false);
                        onOpenSettings('forum-categories');
                      }}
                      className="col-span-2 flex items-center justify-center gap-2 rounded-xl border border-border-default py-2.5 text-xs font-semibold text-text-secondary"
                    >
                      <MessageSquare className="h-3.5 w-3.5" />
                      分类与分类说明
                    </button>
                  </>
                )}
              </div>
              <div
                className="mb-3 rounded-xl border border-border-default bg-surface px-3 py-2.5 text-[11px] text-text-secondary"
                role="status"
                aria-live="polite"
              >
                <div className="flex items-center justify-between gap-2">
                  <span>
                    {generating
                      ? '正在生成论坛内容…'
                      : generationConfig.enabled
                        ? `每 ${generationConfig.everyReplies} 次回复自动更新`
                        : '手动更新模式'}
                  </span>
                  <span>{generationConfig.apiSource === 'custom' ? '自定义 API' : '酒馆 API'}</span>
                </div>
                <div className="mt-1">
                  {generationState.lastGeneratedAt
                    ? `上次更新：${new Date(generationState.lastGeneratedAt).toLocaleString()}`
                    : '尚未生成'}
                </div>
                {(generationState.unreadPostIds?.length || 0) > 0 && (
                  <button
                    type="button"
                    onClick={() => saveForumState({ ...readForumState(), unreadPostIds: [] })}
                    className="mt-2 flex items-center gap-1 text-rose-500"
                  >
                    <Bell className="h-3 w-3" />
                    {generationState.unreadPostIds?.length} 条内容未读 · 全部标为已读
                  </button>
                )}
                {generating && (
                  <div className="mt-2 flex items-center justify-between text-[10px]">
                    <span>超过 {generationConfig.timeoutSeconds} 秒会自动停止</span>
                    <button type="button" onClick={cancel} className="font-bold text-rose-500">
                      取消
                    </button>
                  </div>
                )}
                {generationState.lastError && (
                  <div className="mt-2 flex items-start justify-between gap-2 text-rose-500">
                    <span className="break-words min-w-0">{generationState.lastError}</span>
                    <button
                      type="button"
                      disabled={generating}
                      onClick={() => void handleGenerate()}
                      className="shrink-0 rounded-lg border border-rose-300 px-2 py-1 disabled:opacity-50"
                    >
                      重试
                    </button>
                  </div>
                )}
              </div>
              {confirmClear ? (
                <div className="space-y-3">
                  <p className="text-sm leading-relaxed text-text-secondary">
                    这会清空当前聊天的帖子、点赞、收藏和生成记录，不影响其他聊天。
                  </p>
                  <div className="flex gap-2">
                    <button
                      type="button"
                      onClick={() => setConfirmClear(false)}
                      className="flex-1 rounded-xl border border-border-default py-2 text-xs font-semibold"
                    >
                      取消
                    </button>
                    <button
                      type="button"
                      onClick={handleClear}
                      className="flex-1 rounded-xl bg-rose-500 py-2 text-xs font-semibold text-white"
                    >
                      确认清空
                    </button>
                  </div>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => setConfirmClear(true)}
                  className="flex w-full items-center justify-center gap-2 rounded-xl border border-rose-300 py-2.5 text-xs font-semibold text-rose-500"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                  清空当前聊天论坛
                </button>
              )}
            </section>
          </motion.div>
        )}
        {showHistory && (
          <motion.div
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            className="absolute inset-0 z-50 flex flex-col bg-surface-solid"
          >
            <header className="flex items-center justify-between border-b border-border-default px-4 py-3">
              <button type="button" onClick={() => setShowHistory(false)} className="rounded-full p-2">
                <ChevronLeft className="h-5 w-5" />
              </button>
              <h2 className="font-bold text-text-primary">生成记录</h2>
              <span className="w-9" />
            </header>
            <div className="flex-1 space-y-2 overflow-y-auto p-4">
              {(generationState.records || []).map(record => (
                <button
                  type="button"
                  key={record.id}
                  onClick={() => record.content && setSelectedRecordId(record.id)}
                  disabled={!record.content}
                  className="block w-full rounded-xl border border-border-default p-3 text-left disabled:opacity-60"
                >
                  <div className="flex justify-between gap-2 text-xs font-semibold text-text-primary">
                    <span>
                      {record.status === 'success'
                        ? '生成成功'
                        : record.status === 'timeout'
                          ? '超时'
                          : record.status === 'cancelled'
                            ? '已取消'
                            : '生成失败'}
                    </span>
                    <time>{new Date(record.startedAt).toLocaleString()}</time>
                  </div>
                  <div className="mt-1 text-[11px] text-text-secondary">
                    {record.model} · {(record.durationMs / 1000).toFixed(1)} 秒 · {record.newPosts} 帖 /{' '}
                    {record.newReplies} 回复
                  </div>
                  {record.error && <p className="mt-1 break-words text-[11px] text-rose-500">{record.error}</p>}
                  {record.content && (
                    <p className="mt-2 text-[10px] font-semibold text-[color:var(--action-text)]">
                      {record.status === 'success' ? '点击查看生成内容' : '点击查看原始响应'}
                    </p>
                  )}
                </button>
              ))}
              {!generationState.records?.length && (
                <p className="py-12 text-center text-sm text-text-secondary">暂无生成记录</p>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <AnimatePresence>
        {selectedRecord && (
          <motion.div
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            className="absolute inset-0 z-[60] flex flex-col bg-surface-solid"
          >
            <header className="flex items-center justify-between border-b border-border-default px-4 py-3">
              <button
                type="button"
                onClick={() => setSelectedRecordId(null)}
                aria-label="返回生成记录"
                className="rounded-full p-2"
              >
                <ChevronLeft className="h-5 w-5" />
              </button>
              <h2 className="font-bold text-text-primary">
                {selectedRecord.status === 'success' ? '生成内容' : '原始响应'}
              </h2>
              <span className="w-9" />
            </header>
            <div className="border-b border-border-default px-4 py-3 text-[11px] text-text-secondary">
              {new Date(selectedRecord.startedAt).toLocaleString()} · {selectedRecord.model} · {selectedRecord.newPosts}{' '}
              帖 / {selectedRecord.newReplies} 回复
            </div>
            <pre className="flex-1 overflow-auto whitespace-pre-wrap break-words p-4 font-mono text-xs leading-relaxed text-text-primary">
              {selectedRecord.content || '此记录没有保存生成内容。'}
            </pre>
          </motion.div>
        )}
        {selectedPost && (
          <motion.div
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            className="absolute inset-0 z-40 bg-surface-solid flex flex-col"
          >
            {/* Post Detail Header */}
            <div className="flex items-center justify-between px-4 py-3 sticky top-0 z-10 border-b border-border-default/30">
              <button
                onClick={() => {
                  saveForumState({ ...readForumState(), unreadPostIds: [] });
                  setSelectedId(null);
                }}
                className="w-10 h-10 flex items-center justify-center glass rounded-full hover-fill transition-colors"
              >
                <ChevronLeft className="w-6 h-6 text-text-primary" />
              </button>
              <span className="text-base font-medium text-text-primary truncate flex-1 px-4 text-center">帖子详情</span>
              <div className="w-10 h-10"></div>
            </div>

            <div
              className="flex-1 overflow-y-auto hide-scrollbar bg-surface-solid relative select-none cursor-grab active:cursor-grabbing touch-none pb-4"
              {...detailDragProps}
              ref={detailDragProps.ref}
            >
              {/* Post Content */}
              <div className="p-5 border-b border-border-default">
                <h1 className="text-xl font-bold text-text-primary mb-4 leading-snug">{selectedPost.title}</h1>
                <div className="flex items-center gap-3 mb-5">
                  <div className="w-10 h-10 rounded-full bg-indigo-50 flex items-center justify-center overflow-hidden shrink-0">
                    {selectedPost.authorAvatar ? (
                      <img
                        src={selectedPost.authorAvatar}
                        alt={selectedPost.authorName}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <User className="w-5 h-5 text-indigo-400" />
                    )}
                  </div>
                  <div>
                    <div className="text-sm font-medium text-text-primary">{selectedPost.authorName}</div>
                    <div className="text-[11px] text-text-secondary">{formatTime(selectedPost.timestamp, nowTs)}</div>
                  </div>
                </div>
                <div className="text-base text-text-primary leading-relaxed whitespace-pre-wrap">
                  {selectedPost.content}
                </div>
                <MediaPreview media={selectedPost.media} />

                <div className="flex items-center gap-6 mt-6 pt-4 border-t border-border-default">
                  <button
                    type="button"
                    onClick={() => toggleLike(selectedPost.id)}
                    className={`flex items-center gap-1.5 text-sm transition-colors ${isLiked(selectedPost.id) ? 'text-[color:var(--action-text)]' : 'text-text-secondary hover:text-[color:var(--action-text)]'}`}
                  >
                    <Heart className={`w-5 h-5 ${isLiked(selectedPost.id) ? 'fill-[color:var(--action-text)]' : ''}`} />
                    <span>{displayCount(selectedPost.likes, isLiked(selectedPost.id))}</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => handleToggleFavorite(selectedPost.id)}
                    className={`flex items-center gap-1.5 text-sm transition-colors ${isFavorited(selectedPost.id) ? 'text-amber-500' : 'text-text-secondary hover:text-yellow-500'}`}
                  >
                    <Star className={`w-5 h-5 ${isFavorited(selectedPost.id) ? 'fill-amber-400' : ''}`} />
                    <span>{displayCount(selectedPost.favorites, isFavorited(selectedPost.id))}</span>
                  </button>
                </div>
              </div>

              {/* Replies */}
              <div className="p-5">
                <h3 className="text-sm font-bold text-text-primary mb-4">全部回复 ({selectedPost.replies.length})</h3>
                {selectedPost.replies.map(reply => (
                  <ReplyItem key={reply.id} reply={reply} nowTs={nowTs} />
                ))}
                {selectedPost.replies.length === 0 && (
                  <div className="text-center text-text-secondary mt-10 text-sm">暂无回复，快来抢沙发吧</div>
                )}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showFavorites && (
          <motion.div
            initial={{ x: '100%' }}
            animate={{ x: 0 }}
            exit={{ x: '100%' }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            className="absolute inset-0 z-30 bg-surface-solid flex flex-col"
          >
            <div className="flex items-center justify-between px-4 py-3 sticky top-0 z-10 border-b border-border-default/30">
              <button
                type="button"
                onClick={() => setShowFavorites(false)}
                className="w-10 h-10 flex items-center justify-center glass rounded-full hover-fill transition-colors"
              >
                <ChevronLeft className="w-6 h-6 text-text-primary" />
              </button>
              <span className="text-base font-bold text-text-primary flex-1 px-4 text-center">
                我的收藏 {favoritePosts.length}/{MAX_FORUM_FAVORITES}
              </span>
              <div className="w-10 h-10" />
            </div>
            <div
              className="flex-1 overflow-y-auto px-4 py-4 hide-scrollbar relative select-none cursor-grab active:cursor-grabbing touch-none"
              {...favoriteDragProps}
              ref={favoriteDragProps.ref}
            >
              {favoritePosts.map(post => (
                <div key={post.id} className="relative">
                  {(generationState.unreadPostIds || []).includes(post.id) && (
                    <span className="absolute right-2 top-2 z-10 rounded-full bg-rose-500 px-2 py-0.5 text-[9px] font-bold text-white">
                      新回复
                    </span>
                  )}
                  <PostItem
                    post={post}
                    nowTs={nowTs}
                    liked={isLiked(post.id)}
                    favorited={isFavorited(post.id)}
                    onClick={() => {
                      setShowFavorites(false);
                      handleOpenPost(post.id);
                    }}
                    onToggleLike={() => toggleLike(post.id)}
                    onToggleFavorite={() => handleToggleFavorite(post.id)}
                  />
                </div>
              ))}
              {favoritePosts.length === 0 && (
                <div className="text-center text-text-secondary mt-20 text-sm px-6 leading-relaxed">
                  还没有收藏的帖子。
                  <br />
                  点击星星可收藏，最多 {MAX_FORUM_FAVORITES} 个；收藏后才会继续更新回复。
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </FullScreenModal>
  );
};
