import type { ManifestEntry } from './worldbookManifest';

const STORAGE_KEY = '校园APP_世界书更新记录_v2';
export interface InstalledEntry {
  version: string;
  official: string;
  installed: string;
  uid: number;
  origin: 'official' | 'custom';
  migratedAt: number;
}
export type InstallRecords = Record<string, InstalledEntry>;
export type UpdateStatus = 'new' | 'update' | 'custom' | 'unknown' | 'current' | 'runtime' | 'ambiguous';
export interface WorldbookDiff {
  manifest: ManifestEntry;
  local?: WorldbookEntry;
  status: UpdateStatus;
  record?: InstalledEntry;
  target?: WorldbookEntry;
}

function canonical(value: unknown): unknown {
  if (value instanceof RegExp) return { regexp: value.source, flags: value.flags };
  if (Array.isArray(value)) return value.map(canonical);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).filter(([, item]) => item !== undefined)
      .sort(([a], [b]) => a.localeCompare(b)).map(([key, item]) => [key, canonical(item)]));
  }
  return value;
}

export function entrySnapshot(entry: Partial<WorldbookEntry>): string {
  return JSON.stringify(canonical({
    name: entry.name,
    enabled: entry.enabled,
    content: typeof entry.content === 'string' ? entry.content.replace(/\\n/g, '\n') : entry.content,
    strategy: entry.strategy ? {
      type: entry.strategy.type,
      keys: entry.strategy.keys,
      keys_secondary: entry.strategy.keys_secondary,
    } : undefined,
  }));
}

export function readInstallRecords(): InstallRecords {
  const stored = getVariables({ type: 'character' })[STORAGE_KEY];
  if (stored === undefined) return {};
  if (!stored || typeof stored !== 'object' || Array.isArray(stored)) throw new Error('世界书更新记录损坏，已停止覆盖');
  for (const value of Object.values(stored)) {
    const record = value as InstalledEntry;
    if (!record || typeof record.version !== 'string' || typeof record.official !== 'string'
      || typeof record.installed !== 'string' || typeof record.uid !== 'number'
      || (record.origin !== 'official' && record.origin !== 'custom') || typeof record.migratedAt !== 'number') {
      throw new Error('世界书更新记录损坏，已停止覆盖');
    }
  }
  return stored as InstallRecords;
}

export function recordKey(book: string, id: string): string {
  return JSON.stringify([book, id]);
}

export function saveInstallRecords(records: InstallRecords): void {
  const current = getVariables({ type: 'character' });
  replaceVariables({ ...current, [STORAGE_KEY]: { ...current[STORAGE_KEY], ...records } }, { type: 'character' });
}

export function inspectWorldbook(book: string, entries: WorldbookEntry[], manifest: ManifestEntry[], records: InstallRecords): WorldbookDiff[] {
  return manifest.map(item => {
    const record = records[recordKey(book, item.id)];
    const matches = entries.filter(entry => entry.name === item.name);
    // UID 仅在同一本世界书内用于跟踪玩家重命名，重名时不推断覆盖目标。
    const local = matches[0] ?? (record ? entries.find(entry => entry.uid === record.uid) : undefined);
    if (item.policy === 'runtime') return { manifest: item, local, record, status: 'runtime' };
    if (matches.length > 1) return { manifest: item, local, record, status: 'ambiguous' };
    const target = item.entry ? {
      ...item.entry,
      uid: local?.uid ?? -1,
      enabled: ['校园论坛输出规则', '校园论坛更新需求'].includes(item.name)
        ? false
        : (local?.enabled ?? item.defaultEnabled),
      ...(local?.extra ? { extra: local.extra } : {}),
    } as WorldbookEntry : undefined;
    let status: UpdateStatus;
    if (!local) status = record ? 'unknown' : 'new';
    else if (!record) status = target && entrySnapshot(local) === entrySnapshot(target) ? 'current' : 'unknown';
    else if (record.origin === 'custom' && (record.version !== item.version || record.official !== entrySnapshot(item.entry!))) status = 'custom';
    else if (entrySnapshot(local) !== record.installed) status = 'custom';
    else status = record.version !== item.version || record.official !== entrySnapshot(item.entry!) ? 'update' : 'current';
    return { manifest: item, local, record, target, status };
  });
}

export function needsForce(diff: WorldbookDiff): boolean {
  return diff.status === 'custom' || diff.status === 'unknown';
}

export function canApply(diff: WorldbookDiff): boolean {
  return ['new', 'update', 'custom', 'unknown'].includes(diff.status);
}

export function makeInstallRecord(diff: WorldbookDiff, installed: WorldbookEntry, origin: InstalledEntry['origin'] = 'official'): InstalledEntry {
  return {
    version: diff.manifest.version,
    official: entrySnapshot(diff.manifest.entry!),
    installed: entrySnapshot(installed),
    uid: installed.uid,
    origin,
    migratedAt: Date.now(),
  };
}

export function migrateWorldbookBaseline(book: string, entries: WorldbookEntry[], manifest: ManifestEntry[]): InstallRecords {
  const records = readInstallRecords();
  const migrated: InstallRecords = {};
  for (const diff of inspectWorldbook(book, entries, manifest, records)) {
    const key = recordKey(book, diff.manifest.id);
    if (diff.manifest.policy === 'runtime' || records[key] || !diff.local || !diff.manifest.entry) continue;
    const matchesOfficial = diff.status === 'current';
    migrated[key] = makeInstallRecord(diff, diff.local, matchesOfficial ? 'official' : 'custom');
  }
  saveInstallRecords(migrated);
  return { ...records, ...migrated };
}

export async function applyWorldbookSelections(
  book: string,
  reviewed: WorldbookDiff[],
  manifest: ManifestEntry[],
  forceConfirmed: boolean,
): Promise<WorldbookEntry[]> {
  if (!reviewed.length) throw new Error('请逐条选择更新内容');
  const records = readInstallRecords();
  let applied: WorldbookDiff[] = [];
  const run = updateWorldbookWith(book, current => {
    const fresh = inspectWorldbook(book, current, manifest, records);
    applied = reviewed.map(previous => {
      const diff = fresh.find(item => item.manifest.id === previous.manifest.id);
      if (!diff || !canApply(diff) || !diff.target || (needsForce(diff) && !forceConfirmed)) {
        throw new Error('条目状态已变化，请重新检测后选择');
      }
      if (entrySnapshot(previous.local ?? {}) !== entrySnapshot(diff.local ?? {})
        || previous.local?.uid !== diff.local?.uid) {
        throw new Error(`「${diff.manifest.name}」在预览后已变化，请重新检测`);
      }
      return diff;
    });
    const result = [...current];
    let nextUid = Math.max(-1, ...current.map(entry => entry.uid)) + 1;
    for (const diff of applied) {
      if (diff.local) {
        const index = result.findIndex(entry => entry.uid === diff.local!.uid);
        result[index] = diff.target!;
      } else {
        result.push({ ...diff.target!, uid: nextUid++ });
      }
    }
    return result;
  }, { render: 'immediate' });
  const updated = await run;
  // 只在写入成功并读取宿主补全后的条目后推进各条目的基线，跳过项不推进。
  const persisted = await getWorldbook(book);
  const saved: InstallRecords = {};
  for (const diff of applied) {
    const installed = persisted.find(entry => entry.name === diff.manifest.name);
    if (!installed) throw new Error('更新已写入，但无法确认条目，请重新检测');
    const expected = { ...diff.target!, uid: installed.uid };
    if (entrySnapshot(installed) !== entrySnapshot(expected)) {
      throw new Error(`「${diff.manifest.name}」写入结果与预期不同，未推进更新记录`);
    }
    saved[recordKey(book, diff.manifest.id)] = makeInstallRecord(diff, installed, 'official');
  }
  saveInstallRecords(saved);
  return updated;
}
