export function getInstitutionLabel(type: string): string {
  if (type === '玄幻修仙') return '宗门';
  if (type === '魔法学院') return '学院';
  return '校园';
}

export function getTraitLabel(type: string, trait: string): string {
  return `${trait}${getInstitutionLabel(type)}`;
}

