import { MvuTime } from '../hooks/useMvuData';
import { ChatMessageItem, ChatThread } from '../types';
import { extractFinalBody } from './mvuUpdates';
import { extractBlocks, parseForumClock, readAssistantMessages } from './forumParser';

function normalizeChatType(value: string): 'dm' | 'group' {
  const text = String(value || '').trim();
  if (/群/.test(text) || text === 'group') return 'group';
  return 'dm';
}

export function parseChatImagePayload(raw: string): { kind: 'text' | 'image'; content: string } {
  const text = String(raw || '').trim();
  const match = text.match(/^\[图片\]\s*\[([\s\S]*)\]\s*$/);
  if (match) {
    return { kind: 'image', content: String(match[1] || '').trim() };
  }
  return { kind: 'text', content: text };
}

function parseMessage(block: ReturnType<typeof extractBlocks>[number], fallbackId: string, messageId: number, now?: Partial<MvuTime> | null): ChatMessageItem | null {
  const raw = (block.inner || '').replace(/<[^>]+>/g, '').trim() || String(block.attrs.内容 || '').trim();
  const parsed = parseChatImagePayload(raw);
  const senderName = block.attrs.发送者 || block.attrs.作者 || '匿名同学';
  if (parsed.kind === 'text' && !parsed.content) return null;
  return {
    id: block.attrs.id || fallbackId,
    senderName,
    kind: parsed.kind,
    content: parsed.content,
    timestamp: parseForumClock(block.attrs.时间 || '', messageId, now),
  };
}

function parseThread(block: ReturnType<typeof extractBlocks>[number], fallbackId: string, messageId: number, now?: Partial<MvuTime> | null): ChatThread | null {
  const type = normalizeChatType(block.attrs.类型);
  const target = String(block.attrs.对象 || block.attrs.群名 || '').trim();
  if (!target) return null;
  const messages = extractBlocks(block.inner, '消息')
    .map((item, index) => parseMessage(item, `${block.attrs.id || fallbackId}-m${index + 1}`, messageId, now))
    .filter((item): item is ChatMessageItem => Boolean(item));
  return {
    id: block.attrs.id || fallbackId,
    type,
    target,
    messages,
  };
}

export function normalizeChatName(value: unknown): string {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

export function getChatDisplayName(character: { name: string; nickname?: string; isFriend?: boolean }): string {
  if (character.isFriend && character.nickname) {
    return normalizeChatName(character.nickname);
  }
  return normalizeChatName(character.nickname || character.name);
}

export function getCharacterChatAliases(character?: { name: string; nickname?: string } | null): string[] {
  if (!character) return [];
  return [character.name, character.nickname].map(normalizeChatName).filter(Boolean);
}

export function characterMatchesChatName(character: { name: string; nickname?: string }, name: string): boolean {
  const target = normalizeChatName(name);
  if (!target) return false;
  return getCharacterChatAliases(character).includes(target);
}

function namesMatch(left: string, right: string): boolean {
  return normalizeChatName(left) === normalizeChatName(right);
}

function listIncludesName(list: string[], name: string): boolean {
  const target = normalizeChatName(name);
  return list.some(item => namesMatch(item, target));
}

export interface ChatParseContext {
  playerNames?: string[];
  characters?: Array<{ name: string; nickname?: string; isFriend?: boolean }>;
  groups?: Array<{ name: string; memberNames?: string[] }>;
}

function collectPlayerNames(context?: ChatParseContext): string[] {
  const names = (context?.playerNames || []).map(normalizeChatName).filter(Boolean);
  return [...new Set([...names, '{{user}}', 'user'])];
}

function findMatchedCharacter(
  name: string,
  characters: Array<{ name: string; nickname?: string; isFriend?: boolean }> = [],
) {
  return characters.find(character => characterMatchesChatName(character, name)) || null;
}

function isPlayerOrFriendSender(
  senderName: string,
  playerNames: string[],
  friend: { name: string; nickname?: string } | null,
): boolean {
  if (listIncludesName(playerNames, senderName)) return true;
  return friend ? characterMatchesChatName(friend, senderName) : false;
}

export function isAllowedChatThread(thread: ChatThread, context?: ChatParseContext): boolean {
  if (!context) return true;
  const playerNames = collectPlayerNames(context);
  const characters = context?.characters || [];
  const groups = context?.groups || [];

  if (thread.type === 'dm') {
    const friend = findMatchedCharacter(thread.target, characters);
    if (!friend?.isFriend) return false;
    if (!thread.messages.length) return true;
    return thread.messages.every(message => isPlayerOrFriendSender(message.senderName, playerNames, friend));
  }

  const group = groups.find(item => namesMatch(item.name, thread.target));
  if (!group) return false;
  const members = (group.memberNames || []).map(normalizeChatName).filter(Boolean);
  if (playerNames.length && !playerNames.some(name => listIncludesName(members, name))) {
    return false;
  }
  if (!thread.messages.length) return true;
  return thread.messages.every(message => {
    if (listIncludesName(playerNames, message.senderName)) return true;
    return listIncludesName(members, message.senderName);
  });
}

function parseInlineChatThreads(
  text: string,
  messageId: number,
  now?: Partial<MvuTime> | null,
  context?: ChatParseContext,
): ChatThread[] {
  const playerNames = collectPlayerNames(context);
  const characters = context?.characters || [];
  const groups = context?.groups || [];
  const threads: ChatThread[] = [];
  const pattern = /<(私聊|群聊)>【([^【】]+)】【([^【】]+)】【([\s\S]*?)】<\/\1>/g;
  let match: RegExpExecArray | null;
  let order = 0;
  while ((match = pattern.exec(text))) {
    const [, tag, senderValue, peerValue, contentValue] = match;
    const senderName = normalizeChatName(senderValue);
    const peer = normalizeChatName(peerValue);
    const content = contentValue.trim();
    if (!senderName || !peer || !content) continue;
    const isGroup = tag === '群聊';
    const target = isGroup
      ? peer
      : listIncludesName(playerNames, senderName)
        ? peer
        : listIncludesName(playerNames, peer)
          ? senderName
          : '';
    if (!target) continue;
    const thread: ChatThread = {
      id: `${isGroup ? 'group' : 'dm'}:${target}`,
      type: isGroup ? 'group' : 'dm',
      target,
      messages: [{
        id: `inline-${messageId}-${match.index}`,
        senderName,
        ...parseChatImagePayload(content),
        timestamp: parseForumClock('', messageId, now) + order++,
      }],
    };
    if (isGroup) {
      const group = groups.find(item => namesMatch(item.name, target));
      const members = (group?.memberNames || []).map(normalizeChatName);
      if (!group || !playerNames.some(name => listIncludesName(members, name)) || !listIncludesName(members, senderName)) continue;
    } else {
      const friend = findMatchedCharacter(target, characters);
      if (!friend?.isFriend || !isPlayerOrFriendSender(senderName, playerNames, friend)) continue;
    }
    threads.push(thread);
  }
  return threads;
}

export function parseChatThreadsFromText(
  text: string,
  messageId = 0,
  now?: Partial<MvuTime> | null,
  context?: ChatParseContext,
): ChatThread[] {
  const body = extractFinalBody(text);
  const inlineThreads = parseInlineChatThreads(body, messageId, now, context);
  const containers = extractBlocks(text, '聊天');
  const legacyThreads = containers.flatMap((container, blockIndex) =>
    extractBlocks(container.inner, '会话').map((block, index) =>
      parseThread(block, `chat-${messageId}-${blockIndex + 1}-${index + 1}`, messageId, now),
    ),
  );
  return [...inlineThreads, ...legacyThreads]
    .filter((item): item is ChatThread => Boolean(item))
    .filter(thread => isAllowedChatThread(thread, context));
}

function mergeMessages(current: ChatMessageItem[] = [], incoming: ChatMessageItem[] = []): ChatMessageItem[] {
  const map = new Map<string, ChatMessageItem>();
  [...current, ...incoming].forEach(message => {
    const prev = map.get(message.id);
    if (!prev) {
      map.set(message.id, message);
      return;
    }
    map.set(message.id, { ...prev, ...message, pending: false });
  });
  return [...map.values()].sort((a, b) => a.timestamp - b.timestamp);
}

export function mergeChatThreads(current: ChatThread[], incoming: ChatThread[]): ChatThread[] {
  const map = new Map<string, ChatThread>();
  const keyOf = (thread: ChatThread) => thread.id || `${thread.type}:${thread.target}`;
  [...current, ...incoming].forEach(thread => {
    const key = keyOf(thread);
    const prev = map.get(key);
    if (!prev) {
      map.set(key, thread);
      return;
    }
    map.set(key, {
      ...prev,
      ...thread,
      messages: mergeMessages(prev.messages, thread.messages),
    });
  });
  return [...map.values()];
}

export function loadChatThreadsFromChat(now?: Partial<MvuTime> | null, context?: ChatParseContext): ChatThread[] {
  const threads = readAssistantMessages().flatMap(item => parseChatThreadsFromText(item.message, item.message_id, now, context));
  return mergeChatThreads([], threads).filter(thread => isAllowedChatThread(thread, context));
}

export function getThreadMessages(threads: ChatThread[], type: 'dm' | 'group', target: string, aliases: string[] = []): ChatMessageItem[] {
  const names = new Set([target, ...aliases].map(normalizeChatName).filter(Boolean));
  const matched = threads.filter(thread => thread.type === type && names.has(normalizeChatName(thread.target)));
  return mergeMessages([], matched.flatMap(thread => thread.messages));
}

export function getLatestPreview(messages: ChatMessageItem[]): string {
  const last = messages[messages.length - 1];
  if (!last) return '暂无聊天';
  if (last.kind === 'image') {
    return `${last.senderName}：[图片]${last.content ? ` ${last.content}` : ''}`;
  }
  return `${last.senderName}：${last.content}`;
}
