import { presetCharacterImages } from './presetCharacterImageManifest.generated';

export interface PresetCharacterImages {
  avatar: string;
  portraits: readonly string[];
  portraitLabels: readonly string[];
}

export { presetCharacterImages };

let activeCharacterImages: Record<string, PresetCharacterImages> = { ...presetCharacterImages };

export function setPresetCharacterImages(images: Record<string, PresetCharacterImages>): void {
  activeCharacterImages = images;
}

export function getPresetCharacterImages(name: string, id: string): PresetCharacterImages | undefined {
  return activeCharacterImages[name] || activeCharacterImages[id];
}
