import { useState } from 'react';
import { ChevronDown, ChevronRight, Megaphone, MessageSquare, Moon, MousePointerClick, RefreshCw, Settings, Sun, X } from 'lucide-react';
import { CenterModal, FullScreenModal } from '../ui/Modal';
import { showToast } from '../ui/Toast';
import { useCampusTheme } from '../../hooks/useCampusTheme';
import { useCampusUpdate } from '../../hooks/useCampusUpdate';
import { usePhoneCloseMode } from '../../hooks/usePhoneCloseMode';
import { useForumGeneration } from '../../hooks/useForumGeneration';
import { VERSION, VERSION_HISTORY, UPDATE_LOG } from '../../../../version';
import { WorldbookUpdateModal } from './WorldbookUpdateModal';
import { FrequencySelect } from './FrequencySelect';
import { ForumApiSettings } from './ForumApiSettings';
import { ForumCategorySettings } from './ForumCategorySettings';

function normalizeVersion(value: string) {
  return value.replace(/^v/i, '');
}

type Section = 'updates' | 'theme' | 'close' | 'forum' | 'forum-categories';
type ForumSettingsTab = 'generation' | 'categories' | 'api';

export function AppSettingsScreen({ onClose, initialSection }: { onClose: () => void; initialSection?: Section }) {
  const { result, busy, hasUpdate, refresh, applyUpdate } = useCampusUpdate();
  const { theme, setTheme } = useCampusTheme();
  const { closeMode, setCloseMode } = usePhoneCloseMode();
  const { config: forumConfig, updateConfig: updateForumConfig } = useForumGeneration();
  const [showAnnouncement, setShowAnnouncement] = useState(false);
  const [showWorldbookUpdate, setShowWorldbookUpdate] = useState(false);
  const [expandedSection, setExpandedSection] = useState<Section | null>(initialSection === 'forum-categories' ? 'forum' : initialSection ?? null);
  const [forumSettingsTab, setForumSettingsTab] = useState<ForumSettingsTab>(initialSection === 'forum-categories' ? 'categories' : 'generation');
  const versionChanged = Boolean(result?.latest?.version && normalizeVersion(result.latest.version) !== normalizeVersion(VERSION));

  const toggleSection = (section: Section) => setExpandedSection(current => current === section ? null : section);
  const handleUpdate = async () => {
    showToast('正在清理缓存并重新加载界面…', 'info', 2500);
    try { await applyUpdate(); } catch { showToast('更新失败，请稍后重试', 'error'); }
  };
  const sectionHeader = (section: Section, icon: React.ReactNode, title: string, summary: string) => (
    <button type="button" onClick={() => toggleSection(section)} className="w-full flex items-center gap-3 p-4 text-left hover:bg-surface transition-colors">
      <span className="text-text-secondary shrink-0">{icon}</span><span className="min-w-0 flex-1"><span className="block font-bold text-text-primary">{title}</span><span className="block text-[11px] text-text-secondary mt-1 truncate">{summary}</span></span>
      {section === 'updates' && versionChanged && <span className="text-[9px] font-extrabold text-rose-600 bg-rose-500/10 px-1.5 py-1 rounded">NEW</span>}
      {expandedSection === section ? <ChevronDown className="w-4 h-4 text-text-secondary" /> : <ChevronRight className="w-4 h-4 text-text-secondary" />}
    </button>
  );

  return <FullScreenModal isOpen onClose={onClose} className="z-20">
    <div className="px-6 py-4 shrink-0 border-b border-border-default/30"><h2 className="text-xl font-bold text-text-primary flex items-center gap-2"><Settings className="w-6 h-6 text-text-secondary" />设置</h2></div>
    <div className="flex-1 min-h-0 overflow-y-auto p-5 pb-6 space-y-3 hide-scrollbar">
      <section className="rounded-2xl bg-surface-solid border border-border-default shadow-sm overflow-hidden">{sectionHeader('updates', <RefreshCw className="w-5 h-5" />, '更新检测', hasUpdate ? '发现可用更新' : '检查前端与世界书更新')}{expandedSection === 'updates' && <div className="border-t border-border-default/50 p-4"><div className="text-xs text-text-secondary">当前版本 {result?.version || '--'}{result?.latest?.version ? ` · 最新版本 ${result.latest.version}` : ''}</div>{result?.error && <div className="text-[11px] text-rose-400 mt-1">{result.error}</div>}{result && !hasUpdate && result.channel === 'release' && <div className="text-[11px] text-emerald-500 mt-1">已是最新版本</div>}<div className="flex gap-2 mt-4"><button type="button" onClick={() => setShowAnnouncement(true)} className="flex-1 flex items-center justify-center gap-1 px-2.5 py-2 rounded-lg border border-border-default text-xs font-semibold text-text-secondary hover:bg-surface"><Megaphone className="w-3.5 h-3.5" />公告</button><button type="button" disabled={busy} onClick={() => void refresh().then(next => showToast(next.error || '已重新检测', next.error ? 'error' : 'success', 1500))} className="flex-1 flex items-center justify-center gap-1.5 rounded-lg border border-border-default text-xs font-semibold text-text-secondary disabled:opacity-60"><RefreshCw className={`w-3.5 h-3.5 ${busy ? 'animate-spin' : ''}`} />重新检测</button></div><button type="button" onClick={() => setShowWorldbookUpdate(true)} className="mt-3 w-full flex items-center justify-between rounded-xl border border-border-default bg-surface px-3.5 py-3 text-left hover:border-text-secondary transition-colors"><span><span className="block text-sm font-bold text-text-primary">世界书更新</span><span className="block text-[10px] text-text-secondary mt-1">检查并选择要同步的条目</span></span><ChevronRight className="h-4 w-4 text-text-secondary" /></button>{hasUpdate && <button type="button" disabled={busy} onClick={() => void handleUpdate()} className="mt-3 w-full py-2.5 rounded-xl bg-rose-500 text-white text-xs font-bold disabled:opacity-60">{busy ? '更新中' : '更新前端脚本'}</button>}</div>}</section>
      <section className="rounded-2xl bg-surface-solid border border-border-default shadow-sm overflow-hidden">{sectionHeader('theme', <Sun className="w-5 h-5" />, '主题', `当前：${theme === 'light' ? '日间' : '夜间'}`)}{expandedSection === 'theme' && <div className="border-t border-border-default/50 p-4"><div className="text-[11px] text-text-secondary mb-3">日间与夜间会立刻切换，并记住你的选择</div><div className="grid grid-cols-2 gap-2"><button type="button" onClick={() => setTheme('light')} className={`flex items-center justify-center gap-1.5 py-2.5 rounded-xl text-xs font-bold border ${theme === 'light' ? 'bg-amber-100 text-amber-700 border-amber-200' : 'bg-surface text-text-secondary border-border-default'}`}><Sun className="w-3.5 h-3.5" />日间</button><button type="button" onClick={() => setTheme('dark')} className={`flex items-center justify-center gap-1.5 py-2.5 rounded-xl text-xs font-bold border ${theme === 'dark' ? 'bg-slate-700 text-white border-slate-500' : 'bg-surface text-text-secondary border-border-default'}`}><Moon className="w-3.5 h-3.5" />夜间</button></div></div>}</section>
      <section className="rounded-2xl bg-surface-solid border border-border-default shadow-sm overflow-hidden">
        {sectionHeader('forum', <MessageSquare className="w-5 h-5" />, '论坛设置', forumConfig.enabled ? `每 ${forumConfig.everyReplies} 次回复自动生成` : '已关闭自动生成')}
        {expandedSection === 'forum' && <div className="border-t border-border-default/50 p-4 space-y-3">
          <div role="tablist" aria-label="论坛设置分类" className="grid grid-cols-3 gap-1 rounded-xl bg-surface p-1">{([{ id: 'generation', label: '生成设置' }, { id: 'categories', label: '分类设置' }, { id: 'api', label: '接口设置' }] as const).map(tab => <button key={tab.id} type="button" role="tab" aria-selected={forumSettingsTab === tab.id} onClick={() => setForumSettingsTab(tab.id)} className={`rounded-lg py-2 text-xs font-semibold ${forumSettingsTab === tab.id ? 'bg-surface-solid text-text-primary shadow-sm' : 'text-text-secondary'}`}>{tab.label}</button>)}</div>
          {forumSettingsTab === 'generation' && <div className="space-y-3"><label className="flex items-center justify-between text-xs font-semibold text-text-primary"><span>自动生成论坛内容</span><input type="checkbox" checked={forumConfig.enabled} onChange={event => updateForumConfig({ enabled: event.target.checked })} /></label><div className="flex items-center justify-between gap-3 text-xs font-semibold text-text-primary"><span>生成频率</span><FrequencySelect value={forumConfig.everyReplies} onChange={everyReplies => updateForumConfig({ everyReplies })} options={[1, 2, 3, 5].map(value => ({ value, label: `每 ${value} 次回复` }))} /></div><div className="flex items-center justify-between gap-3 text-xs font-semibold text-text-primary"><span>每轮新帖数</span><FrequencySelect value={forumConfig.postCount} onChange={postCount => updateForumConfig({ postCount })} options={[1, 2, 3, 4, 5].map(value => ({ value, label: `${value} 个帖子` }))} /></div><div className="flex items-center justify-between gap-3 text-xs font-semibold text-text-primary"><span>单次生成超时</span><FrequencySelect value={forumConfig.timeoutSeconds} onChange={timeoutSeconds => updateForumConfig({ timeoutSeconds })} options={[60, 120, 180, 300].map(value => ({ value, label: `${value} 秒` }))} /></div><div className="text-[11px] leading-relaxed text-text-secondary">论坛请求不会创建聊天楼层；历史论坛和聊天标签会从辅助上下文移除。</div></div>}
          {forumSettingsTab === 'categories' && <ForumCategorySettings config={forumConfig} onChange={updateForumConfig} />}
          {forumSettingsTab === 'api' && <ForumApiSettings config={forumConfig} onChange={updateForumConfig} />}
        </div>}
      </section>
      <section className="rounded-2xl bg-surface-solid border border-border-default shadow-sm overflow-hidden">{sectionHeader('close', <MousePointerClick className="w-5 h-5" />, '前端关闭方式', closeMode === 'button' ? '当前：点击关闭按钮关闭' : '当前：点击外部区域关闭')}{expandedSection === 'close' && <div className="border-t border-border-default/50 p-4"><div className="text-[11px] text-text-secondary mb-3">选择如何把校园手机收起成悬浮按钮</div><div className="grid grid-cols-1 gap-2"><button type="button" onClick={() => setCloseMode('button')} className={`flex items-center gap-2 px-3 py-2.5 rounded-xl text-xs font-bold border text-left ${closeMode === 'button' ? 'accent-btn' : 'bg-surface text-text-secondary border-border-default'}`}><X className="w-3.5 h-3.5 shrink-0" /><span>点击关闭按钮关闭</span></button><button type="button" onClick={() => setCloseMode('outside')} className={`flex items-center gap-2 px-3 py-2.5 rounded-xl text-xs font-bold border text-left ${closeMode === 'outside' ? 'accent-btn' : 'bg-surface text-text-secondary border-border-default'}`}><MousePointerClick className="w-3.5 h-3.5 shrink-0" /><span>点击手机前端以外的区域关闭</span></button></div></div>}</section>
    </div>
    <CenterModal isOpen={showAnnouncement} onClose={() => setShowAnnouncement(false)} className="w-full max-w-md max-h-[85%]"><div className="p-4 border-b border-border-default flex items-center justify-between"><div className="flex items-center gap-2 font-bold text-text-primary"><Megaphone className="w-4 h-4" />版本公告</div><button type="button" onClick={() => setShowAnnouncement(false)} className="p-1 text-text-secondary"><X className="w-4 h-4" /></button></div><div className="flex-1 min-h-0 overflow-y-auto p-4 space-y-3"><article className="rounded-xl border border-border-default p-3"><div className="text-sm font-bold text-text-primary">v{normalizeVersion(VERSION)} · 当前版本公告</div><pre className="mt-2 whitespace-pre-wrap break-words text-[11px] leading-relaxed text-text-secondary font-sans">{UPDATE_LOG}</pre></article>{result?.latest?.updateLog && <article className="rounded-xl border border-rose-300/50 bg-rose-500/5 p-3"><div className="text-sm font-bold text-text-primary">v{normalizeVersion(result.latest.version)} <span className="ml-1 text-[9px] text-rose-600">最新公告</span></div><pre className="mt-2 whitespace-pre-wrap break-words text-[11px] leading-relaxed text-text-secondary font-sans">{result.latest.updateLog}</pre></article>}{[...VERSION_HISTORY].reverse().map((release, index) => <article key={`${release.version}-${release.date}`} className="rounded-xl border border-border-default p-3"><div className="flex items-center justify-between text-sm font-bold text-text-primary"><span>v{release.version}</span><span className="text-[10px] font-normal text-text-secondary">{release.date}</span></div><ul className="mt-2 space-y-1">{release.changes.map((change, changeIndex) => <li key={`${index}-${changeIndex}`} className="text-[11px] leading-relaxed text-text-secondary">• {change}</li>)}</ul></article>)}</div></CenterModal>
    {showWorldbookUpdate && <WorldbookUpdateModal onClose={() => setShowWorldbookUpdate(false)} />}
  </FullScreenModal>;
}
