import { useCampusTheme } from '../hooks/useCampusTheme';
import { formatMvuTime, useMvuSnapshot } from '../hooks/useMvuData';
import {
  clickTavernSend,
  clickTavernStop,
  isTavernGenerating,
  getTavernInput,
  setTavernInput,
} from '../utils/fillTavernInput';
import {
  CampusDocument,
  compileTabletHideRules,
  renderTabletMessage,
  replaceTabletBody,
  splitTabletContent,
} from '../utils/tabletContent';
