import { useEffect, useState } from 'react';
import { REQUIRES_WORLDBOOK_UPDATE, UPDATE_LOG, VERSION } from '../../../../version';
import { CenterModal } from '../ui/Modal';

const ACKNOWLEDGED_VERSIONS_KEY = '校园APP_已确认更新公告版本_v2';

function readAcknowledgedVersions(): string[] {
  const stored = getVariables({ type: 'global' })[ACKNOWLEDGED_VERSIONS_KEY];
  return Array.isArray(stored) ? stored.filter((value: unknown): value is string => typeof value === 'string') : [];
}

export function VersionAnnouncement({ enabled = true, onOpenUpdates }: { enabled?: boolean; onOpenUpdates: () => void }) {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (!enabled) return;
    try {
      setOpen(!readAcknowledgedVersions().includes(VERSION));
    } catch (error) {
      console.warn('[校园APP] 无法读取更新公告记录:', error);
      setOpen(true);
    }
  }, [enabled]);

  const acknowledge = () => {
    try {
      const variables = getVariables({ type: 'global' });
      const versions = readAcknowledgedVersions();
      replaceVariables({
        ...variables,
        [ACKNOWLEDGED_VERSIONS_KEY]: [...new Set([...versions, VERSION])],
      }, { type: 'global' });
    } catch (error) {
      console.warn('[校园APP] 无法保存更新公告记录:', error);
    }
    setOpen(false);
  };

  return (
    <CenterModal isOpen={enabled && open} onClose={acknowledge} className="w-full max-w-sm max-h-[85%]">
      <h2 className="shrink-0 border-b border-border-default p-4 text-lg font-bold text-text-primary">更新</h2>
      <div className="min-h-0 flex-1 overflow-y-auto p-4">
        <p className="whitespace-pre-wrap break-words text-xs leading-relaxed text-text-secondary">{UPDATE_LOG}</p>
      </div>
      <div className="shrink-0 border-t border-border-default p-4">
        {REQUIRES_WORLDBOOK_UPDATE && <p className="mb-3 text-xs text-text-secondary">请跳转设置界面进行世界书更新</p>}
        <button type="button" onClick={() => {
          acknowledge();
          if (REQUIRES_WORLDBOOK_UPDATE) onOpenUpdates();
        }} className="w-full rounded-xl bg-rose-500 py-3 text-sm font-bold text-white">{REQUIRES_WORLDBOOK_UPDATE ? '跳转更新' : '我已知晓'}</button>
      </div>
    </CenterModal>
  );
}
