import {
  presetCharacterImages,
  type PresetCharacterImages,
} from './presetCharacterImages';

export const REMOTE_IMAGE_MANIFEST_URL = 'https://pharrellhsk.github.io/image/manifest.json';
const REMOTE_IMAGE_MANIFEST_CACHE_KEY = 'campus-remote-image-manifest-v1';
const MANIFEST_TTL = 60 * 60 * 1000;
let manifestRequest: Promise<Record<string, PresetCharacterImages>> | null = null;

export interface ImageManifest {
  schemaVersion: number;
  baseUrl?: string;
  characters: Record<string, PresetCharacterImages | RemoteCharacterImages>;
}

interface RemoteCharacterImages {
  avatar?: string;
  portraits?: string[];
  portraitLabels?: string[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function toAssetUrl(value: unknown, baseUrl: string): string | null {
  if (typeof value !== 'string' || !value.trim()) return null;
  if (/^(?:https?:|data:|blob:)/i.test(value)) return value;
  return new URL(value.replace(/^\/+/, ''), baseUrl).href;
}

function normalizeCharacter(value: unknown, baseUrl: string): PresetCharacterImages | null {
  if (!isRecord(value)) return null;
  const avatar = toAssetUrl(value.avatar, baseUrl);
  const portraits = Array.isArray(value.portraits)
    ? value.portraits.map(item => toAssetUrl(item, baseUrl)).filter((item): item is string => Boolean(item))
    : [];
  const labels = Array.isArray(value.portraitLabels)
    ? value.portraitLabels.map(String).slice(0, portraits.length)
    : [];
  if (!avatar && !portraits.length) return null;
  return {
    avatar: avatar || portraits[0] || '',
    portraits,
    portraitLabels: portraits.map((_, index) => labels[index] || `立绘${index + 1}`),
  };
}

export function normalizeImageManifest(value: unknown): Record<string, PresetCharacterImages> | null {
  if (!isRecord(value) || !isRecord(value.characters)) return null;
  const baseUrl = typeof value.baseUrl === 'string' && value.baseUrl
    ? new URL(value.baseUrl, REMOTE_IMAGE_MANIFEST_URL).href
    : new URL('./', REMOTE_IMAGE_MANIFEST_URL).href;
  const normalized = Object.fromEntries(
    Object.entries(value.characters)
      .map(([name, images]) => [name, normalizeCharacter(images, baseUrl)] as const)
      .filter((entry): entry is readonly [string, PresetCharacterImages] => Boolean(entry[1])),
  );
  return Object.keys(normalized).length ? normalized : null;
}

function readCachedManifest(): Record<string, PresetCharacterImages> | null {
  try {
    const cached = JSON.parse(localStorage.getItem(REMOTE_IMAGE_MANIFEST_CACHE_KEY) || 'null');
    return normalizeImageManifest(cached);
  } catch {
    return null;
  }
}

function writeCachedManifest(value: unknown): void {
  try {
    localStorage.setItem(REMOTE_IMAGE_MANIFEST_CACHE_KEY, JSON.stringify(value));
  } catch {
    // Storage may be unavailable in private or restricted iframe contexts.
  }
}

export function mergeImageManifests(
  remote: Record<string, PresetCharacterImages> | null,
): Record<string, PresetCharacterImages> {
  return { ...presetCharacterImages, ...(remote || {}) };
}

export function loadRemoteImageManifest(): Promise<Record<string, PresetCharacterImages>> {
  if (!manifestRequest) {
    manifestRequest = fetchImageManifest().finally(() => { manifestRequest = null; });
  }
  return manifestRequest;
}

async function fetchImageManifest(): Promise<Record<string, PresetCharacterImages>> {
  const fallback = mergeImageManifests(readCachedManifest());
  try {
    const cached = JSON.parse(localStorage.getItem(REMOTE_IMAGE_MANIFEST_CACHE_KEY) || 'null');
    if (normalizeImageManifest(cached) && Date.now() - Number(cached.savedAt || 0) < MANIFEST_TTL) return fallback;
  } catch {
    // Fetch remains available when local storage is restricted.
  }
  try {
    const response = await fetch(REMOTE_IMAGE_MANIFEST_URL, { cache: 'no-cache' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const remote = normalizeImageManifest(await response.json());
    if (!remote) throw new Error('Invalid image manifest');
    writeCachedManifest({ schemaVersion: 1, savedAt: Date.now(), baseUrl: 'https://pharrellhsk.github.io/image/', characters: remote });
    return mergeImageManifests(remote);
  } catch (error) {
    console.warn('[校园APP] 远程图片清单加载失败，使用缓存或内置清单:', error);
    return fallback;
  }
}

export function getPresetCharacterImagesFromManifest(
  manifest: Record<string, PresetCharacterImages>,
  name: string,
  id: string,
): PresetCharacterImages | undefined {
  return manifest[name] || manifest[id];
}
