export type ForumCategory = {
  id: string;
  name: string;
  description: string;
  enabled: boolean;
  weight: number;
  aliases?: string[];
};

export const DEFAULT_FORUM_CATEGORIES: ForumCategory[] = [
  { name: '校规吐槽', description: '讨论校规调整、日常检查、纪律执行中的体验与槽点。语气像学生匿名交流，可吐槽但不编造未发生的处罚。' },
  { name: '活动速报', description: '发布社团招新、比赛、演出、讲座和校园活动的现场见闻与实用信息，写清时间地点或参与感受。' },
  { name: '校园八卦', description: '围绕公开可见的校园传闻、同学间的小道消息和围观见闻交流。只能写成有限视角的猜测，不泄露私密剧情或无依据指控。' },
  { name: '求助互助', description: '发布校园生活、课程、失物、路线、设备或活动相关的求助与经验回复，鼓励同学提供具体、友善的帮助。' },
  { name: '闲聊灌水', description: '进行轻松的校园日常闲聊、食堂宿舍天气和学习生活吐槽，口吻自然随意，内容贴合当前剧情。' },
].map(({ name, description }, index) => ({
  id: `default-${index}`,
  name,
  description,
  enabled: true,
  weight: 20,
}));

export function resolveForumBoardName(board: string | undefined, categories: ForumCategory[]): string {
  const name = board?.trim() || '综合';
  const category = categories.find(item => item.name === name)
    || categories.find(item => item.aliases?.includes(name));
  return category?.name || name;
}

export function normalizeForumCategories(value: unknown): ForumCategory[] {
  if (!Array.isArray(value)) return DEFAULT_FORUM_CATEGORIES.map(item => ({ ...item }));
  const ids = new Set<string>();
  const names = new Set<string>();
  const categories = value.slice(0, 20).flatMap(item => {
    if (!item || typeof item !== 'object') return [];
    const source = item as Record<string, unknown>;
    const id = typeof source.id === 'string' ? source.id.trim().slice(0, 80) : '';
    const name = typeof source.name === 'string' ? source.name.trim().slice(0, 24) : '';
    if (!id || !name || name === '全部' || ids.has(id) || names.has(name)) return [];
    ids.add(id);
    names.add(name);
    const rawWeight = Number(source.weight);
    return [{
      id,
      name,
      description: typeof source.description === 'string' ? source.description.slice(0, 4000) : '',
      enabled: source.enabled !== false,
      weight: Number.isFinite(rawWeight) ? Math.round(Math.min(100, Math.max(0, rawWeight))) : 20,
      aliases: Array.isArray(source.aliases) ? source.aliases.filter((alias): alias is string => typeof alias === 'string').map(alias => alias.trim().slice(0, 24)).filter(Boolean).slice(-10) : [],

    }];
  });
  return categories;
}

export function allocateForumCategories(categories: ForumCategory[], count: number): Array<ForumCategory & { count: number }> {
  const eligible = categories.filter(item => item.enabled && item.weight > 0);
  if (!eligible.length) throw new Error('请至少启用一个权重大于 0 的论坛分类');
  const total = eligible.reduce((sum, item) => sum + item.weight, 0);
  const allocated = eligible.map(item => {
    const exact = count * item.weight / total;
    return { ...item, count: Math.floor(exact), remainder: exact - Math.floor(exact) };
  });
  let remaining = Math.max(0, count - allocated.reduce((sum, item) => sum + item.count, 0));
  allocated.sort((a, b) => b.remainder - a.remainder || b.weight - a.weight || a.name.localeCompare(b.name, 'zh-CN'));
  for (let index = 0; index < allocated.length && remaining > 0; index += 1, remaining -= 1) allocated[index].count += 1;
  return allocated.sort((a, b) => a.name.localeCompare(b.name, 'zh-CN')).map(({ remainder: _remainder, ...item }) => item);
}

type ManagedEntry = {
  uid?: number;
  name?: string;
  content?: string;
  enabled?: boolean;
  extra?: Record<string, unknown>;
  [key: string]: unknown;
};

const isManagedCategoryEntry = (entry: ManagedEntry) => entry.extra?.campusAppModule === 'forum-category';
const categoryEntryName = (category: ForumCategory) => `校园论坛分类 · ${category.name}`;

export type ForumCategorySyncPreview = {
  book: string;
  before: string;
  changes: Array<{ id: string; name: string; previous?: string; content: string }>;
};

function resolveForumCategoryWorldbook(): string {
  const chatBook = getChatWorldbookName('current');
  if (chatBook) return chatBook;
  const characterBook = getCharWorldbookNames('current').primary;
  if (characterBook) return characterBook;
  throw new Error('请先绑定聊天世界书或角色主世界书');
}

export async function previewForumCategorySync(categories: ForumCategory[]): Promise<ForumCategorySyncPreview> {
  const book = resolveForumCategoryWorldbook();
  const entries = await getWorldbook(book) as ManagedEntry[];
  const managed = entries.filter(isManagedCategoryEntry);
  return {
    book,
    before: JSON.stringify(managed),
    changes: categories.map(category => ({
      id: category.id,
      name: categoryEntryName(category),
      previous: managed.find(entry => entry.extra?.categoryId === category.id)?.content,
      content: category.description,
    })),
  };
}

export async function syncForumCategoryWorldbook(preview: ForumCategorySyncPreview, categories: ForumCategory[]): Promise<void> {
  const book = resolveForumCategoryWorldbook();
  if (book !== preview.book) throw new Error('世界书绑定已变化，请重新预览');
  await updateWorldbookWith(book, entries => {
    const current = entries as ManagedEntry[];
    if (JSON.stringify(current.filter(isManagedCategoryEntry)) !== preview.before) throw new Error('分类世界书已被修改，请重新预览后确认');
    const existingIds = new Set(current.filter(isManagedCategoryEntry).map(entry => entry.extra?.categoryId));
    let uid = Math.max(-1, ...current.map(entry => Number(entry.uid) || -1)) + 1;
    const next = current.map(entry => {
      if (!isManagedCategoryEntry(entry)) return entry;
      const category = categories.find(item => item.id === entry.extra?.categoryId);
      if (!category) return { ...entry, enabled: false };
      return { ...entry, name: categoryEntryName(category), content: category.description, enabled: false };
    });
    for (const category of categories) {
      if (existingIds.has(category.id)) continue;
      next.push({
        uid: uid++,
        name: categoryEntryName(category),
        content: category.description,
        enabled: false,
        strategy: { type: 'constant', keys: [], keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' },
        position: { type: 'before_character_definition', role: 'system', depth: 0, order: 100 },
        probability: 100,
        recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
        effect: { sticky: null, cooldown: null, delay: null },
        extra: { campusAppModule: 'forum-category', categoryId: category.id },
      });
    }
    return next;
  }, { render: 'immediate' });
}

export async function loadForumCategoryDescriptions(categories: ForumCategory[]): Promise<ForumCategory[]> {
  try {
    const book = resolveForumCategoryWorldbook();
    const entries = await getWorldbook(book) as ManagedEntry[];
    return categories.map(category => {
      const entry = entries.find(item => isManagedCategoryEntry(item) && item.extra?.categoryId === category.id);
      return entry?.content ? { ...category, description: entry.content.slice(0, 4000) } : category;
    });
  } catch {
    return categories;
  }
}

