import { extractFinalBody, stripMvuBlocks } from './mvuUpdates';

export interface CampusDocument {
  kind?: 'player-profile';
  footer?: string;
  label: string;
  office: string;
  title: string;
  subject: string;
  fields: Array<[string, string]>;
  raw: string;
}

export type TabletPart = { type: 'text'; raw: string } | { type: 'document'; raw: string; document: CampusDocument };

export function parseCampusDocument(raw: string): CampusDocument | null {
  const text = raw.trim();
  const fields: Array<[string, string]> = [];
  const add = (label: string, value?: string) => {
    if (value) fields.push([label, value]);
  };
  let match = text.match(
    /^在校园新增建筑「([^」]+)」，坐标为 X=([^、]+)、Y=([^，]+)，宽度 ([^ ]+) 格、高度 ([^ ]+) 格，建筑描述为「([\s\S]*?)」。建筑类型设为「([^」]+)」。请通过 MVU 变量更新写入「校园建筑」，保留其他建筑数据。$/,
  );
  if (match) {
    add('建筑用途', match[7]);
    add('规划位置', `X=${match[2]}，Y=${match[3]}`);
    add('占地尺寸', `${match[4]} × ${match[5]} 格`);
    add('建设说明', match[6]);
    return { label: '新增建筑', office: '校施工队', title: '施工许可证', subject: match[1], fields, raw };
  }
  const createRule = text.match(
    /^在校规(?:的(.+?)分类中|中新增(.+?)分类，并于其中)新增校规(.+?)，校规内容为：“([\s\S]*)”，生效地点为([\s\S]+)。$/,
  );
  if (createRule) {
    add('校规分类', createRule[1] || createRule[2]);
    add('公告内容', createRule[4]);
    add('适用地点', createRule[5]);
    return { label: '新增校规', office: '校务处', title: '校规公告', subject: createRule[3], fields, raw };
  }
  const editRule = text.match(
    /^(?:在校规中新增.+?分类，并)?将原校规「([^」]+)」修改为：标题为「([^」]+)」，分类为「([^」]+)」，校规内容为：“([\s\S]*)”，生效地点为([\s\S]+)。$/,
  );
  if (editRule) {
    add('原校规', editRule[1]);
    add('校规分类', editRule[3]);
    add('修订内容', editRule[4]);
    add('适用地点', editRule[5]);
    return { label: '修改校规', office: '校务处', title: '校规修订通知', subject: editRule[2], fields, raw };
  }
  match = text.match(/^删除校规「([^」]+)」，该校规原本属于「([^」]+)」分类。$/);
  if (match)
    return {
      label: '删除校规',
      office: '校务处',
      title: '校规废止公告',
      subject: match[1],
      fields: [['校规分类', match[2]]],
      raw,
    };
  match = text.match(/^将校规「([^」]+)」(重新启用，并按原分类「([^」]+)」继续生效|关闭，使其暂时不再生效)。$/);
  if (match)
    return {
      label: match[3] ? '启用校规' : '停用校规',
      office: '校务处',
      title: match[3] ? '校规恢复通知' : '校规暂停通知',
      subject: match[1],
      fields: match[3] ? [['校规分类', match[3]]] : [],
      raw,
    };
  match = text.match(
    /^(?:在「([^」]+)」内新增地点：|修改「([^」]+)」内原名为「([^」]+)」的地点，改为：)(\{[^\n]+?\})。[\s\S]*请通过 MVU 变量更新写入「校园建筑」中对应建筑的地点及分区，不生成地点或分区 ID，不覆盖其他地点、分区和建筑数据。$/,
  );
  if (match) {
    try {
      const data = JSON.parse(match[4]) as Record<string, unknown>;
      add('所在建筑', match[1] || match[2]);
      add('原地点', match[3]);
      for (const key of ['所属分区', '类型', '描述']) if (typeof data[key] === 'string') add(key, data[key]);
      if (typeof data.名称 !== 'string') return null;
      return {
        label: match[1] ? '新增地点' : '修改地点',
        office: '校园建设处',
        title: '场所变更单',
        subject: data.名称,
        fields,
        raw,
      };
    } catch {
      return null;
    }
  }
  match = text.match(
    /^(?:在「([^」]+)」添加活动：|将「([^」]+)」中的「([^」]+)」活动修改为：)活动名称：([^，]+)，开始时间：([^，]+)，结束时间：([^，]+)，活动描述：([\s\S]+)。请写入「([^」]+)」的建筑活动(?:（含活动环节）)?。$/,
  );
  if (match) {
    add('所在建筑', match[1] || match[2]);
    add('原活动', match[3]);
    add('开始时间', match[5]);
    add('结束时间', match[6]);
    add('活动安排', match[7]);
    return {
      label: match[1] ? '新增活动' : '修改活动',
      office: '校园活动部',
      title: '活动安排单',
      subject: match[4],
      fields,
      raw,
    };
  }
  match = text.match(/^(?:在群聊「([^」]+)」中发送消息：|给「([^」]+)」发私聊：)([\s\S]+)$/);
  if (match)
    return {
      label: match[1] ? '群聊消息' : '私聊消息',
      office: '校园通信',
      title: match[1] ? '群聊留言' : '私人便笺',
      subject: match[1] || match[2],
      fields: [['留言内容', match[3]]],
      raw,
    };
  return null;
}

export function splitTabletContent(raw: string): TabletPart[] {
  if (raw.trimStart().startsWith('【开篇请求】') && /玩家档案[：:]/.test(raw)) {
    const fields: Array<[string, string]> = [];
    const labels: Record<string, string> = { 当前选择前往: '始发地' };
    let direction: string[] | null = null;
    let footer = '';
    for (const line of raw.split(/\r?\n/)) {
      const field = line.match(/^\s*-\s*([^：:]+)[：:]\s*(.*)$/);
      if (field && direction === null) {
        const label = field[1].trim();
        fields.push([labels[label] || label, field[2].trim()]);
      } else if (line.trim() === '玩家指定的开局走向：') {
        direction = [];
      } else if (line.startsWith('请结合上述开局走向') || line.startsWith('请以玩家选择前往')) {
        if (line.startsWith('请以玩家选择前往')) footer = line.trim();
      } else if (direction !== null) {
        direction.push(line);
      }
    }
    if (direction?.join('\n').trim()) fields.push(['开局走向', direction.join('\n').trim()]);
    if (fields.length) {
      return [{
        type: 'document',
        raw,
        document: {
          kind: 'player-profile',
          label: '入学档案',
          office: '圣樱学院',
          title: 'Player Profile',
          subject: fields.find(([key]) => key === '姓名')?.[1] || '玩家档案',
          fields,
          footer,
          raw,
        },
      }];
    }
  }
  const lines = raw.split(/(?<=\n)/);
  const parts: TabletPart[] = [];
  for (let index = 0; index < lines.length; index += 1) {
    let line = lines[index];
    let document = parseCampusDocument(line);
    if (!document && /^(?:在校园新增建筑「|在校规|将原校规「|修改「)/.test(line)) {
      let candidate = line;
      for (let end = index + 1; end < lines.length; end += 1) {
        candidate += lines[end];
        const parsed = parseCampusDocument(candidate);
        if (parsed) {
          line = candidate;
          document = parsed;
          index = end;
          break;
        }
      }
    }
    const previous = parts[parts.length - 1];
    if (document) parts.push({ type: 'document', raw: line, document });
    else if (previous?.type === 'text') previous.raw += line;
    else parts.push({ type: 'text', raw: line });
  }
  return parts;
}

export function replaceTabletBody(parts: TabletPart[], body: string): string {
  const firstText = parts.findIndex(part => part.type === 'text');
  if (firstText < 0) return `${parts.map(part => part.raw).join('')}${body ? `\n${body}` : ''}`;
  let result = '';
  for (let index = 0; index < parts.length; index += 1) {
    const part = parts[index];
    if (part.type === 'document') {
      if (result && !result.endsWith('\n')) result += '\n';
      result += part.raw;
    } else if (index === firstText) {
      result += body;
      if (body && !body.endsWith('\n') && parts.slice(index + 1).some(item => item.type === 'document')) result += '\n';
    }
  }
  return result;
}

const ALLOWED_TAGS = new Set([
  'p',
  'br',
  'strong',
  'em',
  'b',
  'i',
  'u',
  's',
  'span',
  'div',
  'blockquote',
  'ul',
  'ol',
  'li',
  'hr',
  'h1',
  'h2',
  'h3',
  'h4',
  'pre',
  'code',
  'table',
  'thead',
  'tbody',
  'tr',
  'th',
  'td',
  'details',
  'summary',
  'a',
  'img',
  'sup',
  'sub',
]);
const DROP_TAGS = new Set([
  'script',
  'style',
  'iframe',
  'object',
  'embed',
  'form',
  'input',
  'button',
  'textarea',
  'svg',
  'math',
  'link',
  'meta',
  'template',
]);

export function sanitizeTabletHtml(html: string): string {
  const source = new DOMParser().parseFromString(html, 'text/html');
  source
    .querySelectorAll('.sakura-thinking, .sakura-complete, UpdateVariable, UpdateVariablevariable, Analysis, JSONPatch')
    .forEach(element => element.remove());
  const output = document.createElement('div');
  const append = (node: Node, parent: HTMLElement) => {
    if (node.nodeType === 3) {
      parent.appendChild(document.createTextNode(node.textContent || ''));
      return;
    }
    if (node.nodeType !== 1) return;
    const element = node as Element;
    const tag = element.tagName.toLowerCase();
    if (DROP_TAGS.has(tag)) return;
    if (!ALLOWED_TAGS.has(tag)) {
      for (const child of Array.from(node.childNodes)) append(child, parent);
      return;
    }
    const safe = document.createElement(tag);
    if (tag === 'a' || tag === 'img') {
      const attr = tag === 'a' ? 'href' : 'src';
      const value = element.getAttribute(attr) || '';
      try {
        const url = new URL(value, window.parent.location.href);
        if (value && ['http:', 'https:'].includes(url.protocol)) safe.setAttribute(attr, url.href);
      } catch {
        /* Invalid URLs are rendered without navigation or media. */
      }
      if (tag === 'a') {
        safe.setAttribute('target', '_blank');
        safe.setAttribute('rel', 'noopener noreferrer');
      } else {
        safe.setAttribute('alt', element.getAttribute('alt') || '图片');
        safe.setAttribute('loading', 'lazy');
      }
    }
    for (const child of Array.from(node.childNodes)) append(child, safe);
    parent.appendChild(safe);
  };
  for (const node of Array.from(source.body.childNodes)) append(node, output);
  return output.innerHTML;
}

export function compileTabletHideRules(value: string): RegExp[] {
  return value
    .split(/\r?\n/)
    .filter(line => line.trim())
    .map(line => {
      const source = line.trim();
      const literal = source.match(/^\/([\s\S]*)\/([dgimsuvy]*)$/);
      const flags = (literal?.[2] || '').replace(/[gy]/g, '');
      const expression = new RegExp(literal?.[1] ?? source, `${flags}g`);
      if (expression.test('')) throw new Error('隐藏规则不能匹配空文本。');
      expression.lastIndex = 0;
      return expression;
    });
}

export function decorateTabletProse(html: string, avatars: Record<string, string> = {}): string {
  const root = document.createElement('div');
  root.innerHTML = html;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes: Text[] = [];
  while (walker.nextNode()) {
    const node = walker.currentNode as Text;
    if (!node.parentElement?.closest('pre, code, a, summary, .campus-prose-thought, .campus-prose-dialogue'))
      nodes.push(node);
  }
  for (const node of nodes) {
    const fragment = document.createDocumentFragment();
    const pattern = /【([^【】\r\n]{1,30})】([^\r\n]+)|“([^”\r\n]+)”|"([^"\r\n]+)"/g;
    const text = node.data;
    let cursor = 0;
    for (const match of text.matchAll(pattern)) {
      fragment.append(document.createTextNode(text.slice(cursor, match.index)));
      if (match[1]) {
        const card = document.createElement('span');
        card.className = 'campus-prose-thought';
        const avatar = document.createElement('span');
        avatar.className = 'campus-prose-thought-avatar';
        avatar.setAttribute('aria-hidden', 'true');
        avatar.textContent = match[1].trim().slice(0, 1);
        const imageUrl = avatars[match[1].trim()];
        if (imageUrl && /^(https?:\/\/|data:image\/(?:png|jpeg|webp|gif);base64,|blob:)/i.test(imageUrl)) {
          const image = document.createElement('img');
          image.src = imageUrl;
          image.alt = '';
          avatar.replaceChildren(image);
        }
        const content = document.createElement('span');
        content.className = 'campus-prose-thought-content';
        const name = document.createElement('strong');
        name.textContent = match[1].trim();
        const thought = document.createElement('span');
        thought.className = 'campus-prose-thought-text';
        thought.textContent = match[2].trim();
        content.append(name, thought);
        card.append(avatar, content);
        fragment.append(card);
      } else {
        const dialogue = document.createElement('span');
        dialogue.className = 'campus-prose-dialogue';
        dialogue.textContent = match[0];
        fragment.append(dialogue);
      }
      cursor = match.index! + match[0].length;
    }
    if (!cursor) continue;
    fragment.append(document.createTextNode(text.slice(cursor)));
    node.replaceWith(fragment);
  }
  return root.innerHTML;
}

export function renderTabletMessage(
  raw: string,
  messageId: number,
  streaming = false,
  avatars: Record<string, string> = {},
  hideRules = '',
): string {
  if (streaming) {
    // Display regexes and HTML parsing can consume unfinished or quoted protocol tags.
    const escaped = document.createElement('div');
    escaped.textContent = raw;
    return escaped.innerHTML.replace(/\n/g, '<br>');
  }
  raw = stripMvuBlocks(extractFinalBody(raw));
  const triggers: Array<{ token: string; target: string; sender: string; peer: string; content: string; key: string }> = [];
  raw = raw.replace(/(?:\r?\n[ \t]*)*^[ \t]*<群聊>[\s\S]*?<\/群聊>[ \t]*(?:\r?\n[ \t]*)*/gm, '\n\n');
  raw = raw.replace(/<(私聊|群聊)>【([^【】]+)】【([^【】]+)】【([\s\S]*?)】<\/\1>/g, (tag, type, sender, peer, content, offset) => {
    if (type !== '私聊') return '';
    const target = String(sender).trim() === '{{user}}' ? String(peer).trim() : String(sender).trim();
    const token = `CAMPUSCHATTRIGGER${triggers.length}END`;
    triggers.push({ token, target, sender: String(sender).trim(), peer: String(peer).trim(), content: String(content).trim(), key: `${messageId}-${offset}-${target}` });
    return token;
  });
  raw = raw.replace(/(?:\r?\n[ \t]*)+(CAMPUSCHATTRIGGER\d+END)[ \t]*(?=\r?\n|$)/g, '$1');
  try {
    for (const rule of compileTabletHideRules(hideRules)) raw = raw.replace(rule, '');
  } catch (reason) {
    console.warn('[校园平板] 隐藏规则无效', reason);
  }
  try {
    // This host formatter already applies macros, display regexes and Markdown once.
    const sanitized = sanitizeTabletHtml(formatAsDisplayedMessage(raw, { message_id: messageId }));
    const safe = document.createElement('div');
    safe.innerHTML = sanitized;
    triggers.forEach(trigger => {
      const walker = document.createTreeWalker(safe, NodeFilter.SHOW_TEXT);
      const textNodes: Text[] = [];
      while (walker.nextNode()) textNodes.push(walker.currentNode as Text);
      for (const node of textNodes) {
        const index = node.data.indexOf(trigger.token);
        if (index < 0) continue;
        const before = node.data.slice(0, index);
        const after = node.data.slice(index + trigger.token.length);
        const marker = document.createElement('span');
        marker.className = 'campus-chat-trigger';
        marker.dataset.chatKey = trigger.key;
        marker.dataset.chatTarget = trigger.target;
        marker.dataset.chatContent = trigger.content;
        marker.dataset.chatSender = trigger.sender;
        marker.dataset.chatPeer = trigger.peer;
        marker.setAttribute('aria-hidden', 'true');
        node.replaceWith(document.createTextNode(before), marker, document.createTextNode(after));
        const paragraph = marker.closest('p');
        if (paragraph && !paragraph.textContent?.trim() && !paragraph.querySelector('img, video, audio, table')) {
          // Keep the read position at the preceding prose without retaining a marker-only paragraph.
          const previous = paragraph.previousElementSibling;
          if (previous?.matches('p, blockquote, li, div')) previous.append(marker);
          else paragraph.before(marker);
          if (!paragraph.querySelector('.campus-chat-trigger')) paragraph.remove();
        }
        break;
      }
    });
    return decorateTabletProse(safe.innerHTML, avatars);
  } catch (error) {
    console.warn('[校园平板] 消息美化失败，显示原文', error);
    const visible = stripMvuBlocks(extractFinalBody(raw));
    const escaped = document.createElement('div');
    escaped.textContent = visible;
    return decorateTabletProse(escaped.innerHTML.replace(/\n/g, '<br>'), avatars);
  }
}
