import { CachedImage } from './CachedImage';
import React, { useRef, useState } from 'react';
import { Camera } from 'lucide-react';
import { ImageCropModal } from './ImageCropModal';

interface ImageUploadProps {
  currentImage: string | null;
  onUpload: (dataUrl: string) => void;
  className?: string;
}

export function ImageUpload({ currentImage, onUpload, className = '' }: ImageUploadProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [tempImageSrc, setTempImageSrc] = useState<string | null>(null);
  const [isCropperOpen, setIsCropperOpen] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setTempImageSrc(reader.result as string);
        setIsCropperOpen(true);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleCropConfirm = (croppedDataUrl: string) => {
    onUpload(croppedDataUrl);
    setIsCropperOpen(false);
    setTempImageSrc(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleCropCancel = () => {
    setIsCropperOpen(false);
    setTempImageSrc(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  return (
    <>
      <div 
        className={`relative group cursor-pointer overflow-hidden bg-surface backdrop-blur-sm border border-border-default shadow-sm flex items-center justify-center ${className}`}
        onClick={() => fileInputRef.current?.click()}
      >
        {currentImage ? (
          <CachedImage src={currentImage} alt="Avatar" className="w-full h-full object-cover" />
        ) : (
          <Camera className="w-8 h-8 text-[color:var(--action-text)] opacity-50 group-hover:opacity-100 transition-opacity" />
        )}
        <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
          <Camera className="w-6 h-6 text-white" />
        </div>
        <input 
          type="file" 
          ref={fileInputRef} 
          className="hidden" 
          accept="image/*"
          onChange={handleFileChange}
        />
      </div>

      <ImageCropModal
        isOpen={isCropperOpen}
        imageSrc={tempImageSrc}
        onConfirm={handleCropConfirm}
        onCancel={handleCropCancel}
      />
    </>
  );
}
