import { BuildingEvent, CampusBuilding, CampusPlace, CampusZone, SchoolRule } from '../types';

export const WORKSHOP_PACK_KIND = 'campus-workshop';
export const WORKSHOP_PACK_VERSION = 1;
export const RULE_CATEGORY_ORDER = ['前言', '学习纪律', '生活纪律', '社交礼仪', '校园安全', '奖惩制度'];
const BUILDING_COLORS: Record<string, string> = {
  餐饮娱乐: 'bg-[#FFEDD4] border-[#FAC280]',
  学习设施: 'bg-[#DBEAFE] border-[#91C6FF]',
  运动设施: 'bg-[#FFE2E2] border-[#FDA6A5]',
  宿舍生活: 'bg-[#F3E8FF] border-[#DAB5FD]',
  自然环境: 'bg-[#DBFCE7] border-[#7BF1A8]',
};

export interface WorkshopRulePack {
  id: string;
  title: string;
  content: string;
  category: string;
  enabled: boolean;
  locationNames: string[];
}

export interface WorkshopArchivePack {
  name: string;
  content: string;
  enabled: boolean;
  campusType?: string;
  displayName?: string;
}

export interface WorkshopBuildingEventPack {
  name: string;
  description: string;
  startTime: number;
  endTime: number;
}

export interface WorkshopBuildingPack {
  id: string;
  name: string;
  x: number;
  y: number;
  width: number;
  height: number;
  color?: string;
  buildingType?: string;
  description?: string;
  zones?: CampusZone[];
  places?: CampusPlace[];
  events?: WorkshopBuildingEventPack[];
}

export interface WorkshopPack {
  kind: typeof WORKSHOP_PACK_KIND;
  version: number;
  name: string;
  exportedAt: string;
  rules: WorkshopRulePack[];
  characters: WorkshopArchivePack[];
  activities: WorkshopArchivePack[];
  buildings: WorkshopBuildingPack[];
}

export function toWorkshopRule(rule: SchoolRule): WorkshopRulePack {
  return {
    id: rule.id,
    title: rule.title,
    content: rule.content,
    category: rule.category || '其他',
    enabled: rule.enabled !== false,
    locationNames: Array.isArray(rule.locationNames) ? rule.locationNames : [],
  };
}

export function fromWorkshopRule(rule: WorkshopRulePack, id: string): SchoolRule {
  return {
    id,
    title: String(rule.title || '').trim() || id,
    content: String(rule.content || ''),
    category: String(rule.category || '其他'),
    enabled: rule.enabled !== false,
    locationNames: Array.isArray(rule.locationNames) ? rule.locationNames.map(String) : [],
  };
}

export function toWorkshopBuilding(building: CampusBuilding, buildingType?: string): WorkshopBuildingPack {
  return {
    id: building.id || building.name,
    name: building.name,
    x: building.x,
    y: building.y,
    width: building.width,
    height: building.height,
    color: building.color,
    buildingType,
    description: building.description || '',
    zones: building.zones || [],
    places: building.places || [],
    events: (building.events || []).map(event => ({
      name: event.name,
      description: event.description,
      startTime: event.startTime,
      endTime: event.endTime,
    })),
  };
}

export function fromWorkshopBuilding(item: WorkshopBuildingPack): CampusBuilding {
  const buildingType = String(item.buildingType || '').trim();
  return {
    id: String(item.id || item.name).trim() || item.name,
    name: String(item.name || '').trim(),
    x: Number(item.x) || 0,
    y: Number(item.y) || 0,
    width: Number(item.width) || 5,
    height: Number(item.height) || 3,
    color: item.color || BUILDING_COLORS[buildingType] || BUILDING_COLORS.学习设施,
    description: String(item.description || ''),
    zones: Array.isArray(item.zones) ? item.zones : [],
    places: Array.isArray(item.places) ? item.places : [],
    facilityType: buildingType || undefined,
    events: Array.isArray(item.events)
      ? item.events.map((event, index) => ({
          id: `${item.name}-${index}`,
          name: String(event.name || `活动${index + 1}`),
          description: String(event.description || ''),
          startTime: Number(event.startTime) || 0,
          endTime: Number(event.endTime) || 0,
          stages: [],
        } satisfies BuildingEvent))
      : [],
  };
}

export function uniqueRuleId(existing: Set<string>, preferred: string): string {
  const base = String(preferred || '').trim() || `workshop-rule-${Date.now()}`;
  if (!existing.has(base)) return base;
  let index = 2;
  while (existing.has(`${base}-${index}`)) index += 1;
  return `${base}-${index}`;
}

export function parseWorkshopPack(raw: unknown): WorkshopPack {
  const data = raw && typeof raw === 'object' ? (raw as Record<string, unknown>) : {};
  const asList = <T>(value: unknown): T[] => (Array.isArray(value) ? (value as T[]) : []);
  return {
    kind: WORKSHOP_PACK_KIND,
    version: Number(data.version) || WORKSHOP_PACK_VERSION,
    name: String(data.name || '').trim(),
    exportedAt: String(data.exportedAt || ''),
    rules: asList<WorkshopRulePack>(data.rules).filter(item => item && (item.title || item.content)),
    characters: asList<WorkshopArchivePack>(data.characters).filter(item => item && item.name && item.content),
    activities: asList<WorkshopArchivePack>(data.activities).filter(item => item && item.name && item.content),
    buildings: asList<WorkshopBuildingPack>(data.buildings).filter(item => item && item.name),
  };
}

export function sanitizeFileName(name: string): string {
  return String(name || '').replace(/[\\/:*?"<>|]/g, '_').replace(/\s+/g, ' ').trim() || '圣樱工坊';
}

export function downloadWorkshopPack(pack: WorkshopPack, fileName: string) {
  const blob = new Blob([JSON.stringify(pack, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `${sanitizeFileName(fileName)}.json`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function formatLocations(locationNames?: string[]): string {
  if (!locationNames || locationNames.length === 0 || locationNames.includes('全校')) return '全校';
  return locationNames.join('、');
}

export function formatRulePrompt(rule: SchoolRule, existingCategories: string[] = []): string {
  const category = rule.category?.trim() || '其他';
  const title = rule.title.trim();
  const content = rule.content.trim();
  const locations = formatLocations(rule.locationNames);
  return existingCategories.includes(category)
    ? `在校规的${category}分类中新增校规${title}，校规内容为：“${content}”，生效地点为${locations}。`
    : `在校规中新增${category}分类，并于其中新增校规${title}，校规内容为：“${content}”，生效地点为${locations}。`;
}

export function groupRulesByCategory(rules: SchoolRule[]): { category: string; rules: SchoolRule[] }[] {
  const groups = new Map<string, SchoolRule[]>();
  for (const category of RULE_CATEGORY_ORDER) groups.set(category, []);
  for (const rule of rules) {
    const category = rule.category?.trim() || '其他';
    if (!groups.has(category)) groups.set(category, []);
    groups.get(category)!.push(rule);
  }
  return [...groups.entries()]
    .filter(([, items]) => items.length)
    .map(([category, items]) => ({ category, rules: items }));
}
