export type UpdateChange = { path: string[]; before: unknown; after: unknown };
export type UpdateNotice = { title: string; category: string; changes: UpdateChange[] };

export function diffMvu(before: unknown, after: unknown, path: string[] = []): UpdateChange[] {
  if (_.isEqual(before, after)) return [];
  const object = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v);
  if (object(before) && object(after)) {
    return [...new Set([...Object.keys(before), ...Object.keys(after)])]
      .filter(key => !key.startsWith('$') && !key.startsWith('_'))
      .flatMap(key => diffMvu(before[key], after[key], [...path, key]));
  }
  return [{ path, before, after }];
}

export function describeMvuChanges(changes: UpdateChange[]): UpdateNotice[] {
  const groups = new Map<string, UpdateNotice>();
  changes.forEach(change => {
    const [root, name, field] = change.path;
    const category =
      root === '校园建筑'
        ? change.path.some(p => ['地点', '分区'].includes(p))
          ? '地点'
          : '建筑'
        : root === '角色' || root === '玩家'
          ? '人物'
          : root === '校规'
            ? '校规'
            : root || '校园';
    const subject = root === '校规' ? change.path.slice(1, 3).join(' · ') : root === '玩家' ? '玩家' : name || root;
    const key = `${category}/${subject}`;
    if (!groups.has(key)) groups.set(key, { category, title: `${subject} · ${category}更新`, changes: [] });
    groups.get(key)!.changes.push(change);
    if (!name && !field) groups.get(key)!.title = `${root}更新`;
  });
  return [...groups.values()];
}

export function displayMvuValue(value: unknown): string {
  if (value === undefined) return '未设置';
  if (value === null) return '空';
  if (typeof value === 'boolean') return value ? '是' : '否';
  if (typeof value === 'object') return JSON.stringify(value, null, 2);
  return String(value);
}

export function checkMvuPatchResult(text: string, data: unknown): string | undefined {
  const inspected = inspectMvuCode(text);
  if (inspected.error) return inspected.error;
  const block = inspected.code.match(/<JSONPatch>([\s\S]*?)<\/JSONPatch>/i);
  if (!block) return undefined;
  const patches = JSON.parse(block[1].replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, '')) as Array<{
    op: string;
    path: string;
    value?: unknown;
  }>;
  const failed = patches.filter((patch, index) => {
    // Later writes to the same subtree and array removals can invalidate intermediate targets.
    if (
      patches
        .slice(index + 1)
        .some(
          next =>
            next.path === patch.path ||
            next.path.startsWith(`${patch.path}/`) ||
            patch.path.startsWith(`${next.path}/`) ||
            next.op === 'remove',
        )
    )
      return false;
    const path = patch.path
      .slice(1)
      .split('/')
      .map(key => key.replace(/~1/g, '/').replace(/~0/g, '~'));
    if (path.includes('-')) return false;
    return patch.op === 'remove' ? _.has(data, path) : !_.isEqual(_.get(data, path), patch.value);
  });
  return failed.length
    ? `有 ${failed.length} 项指令目标与变量结果不一致（如 ${failed[0].path}）。请检查路径是否存在、对象是否允许扩展及 MVU 校验报错。`
    : undefined;
}

export function extractFinalBody(text: string): string {
  const bodyStart = text.lastIndexOf('<正文>');
  if (bodyStart >= 0) {
    const content = text.slice(bodyStart + '<正文>'.length);
    const bodyEnd = content.indexOf('</正文>');
    return bodyEnd >= 0 ? content.slice(0, bodyEnd) : content;
  }
  const mvuStart = [...text.matchAll(/<UpdateVariable(?:variable)?\s*>/gi)].at(-1);
  const finalText = mvuStart ? text.slice(0, mvuStart.index) : text;
  return finalText;
}

export function extractFinalMvuBlock(text: string): string {
  const starts = [...text.matchAll(/<UpdateVariable(?:variable)?\s*>/gi)];
  const start = starts.at(-1);
  if (!start) return '';
  const content = text.slice(start.index!);
  const end = /<\/UpdateVariable(?:variable)?\s*>/i.exec(content);
  return end ? content.slice(0, end.index + end[0].length) : content;
}

export function hasMvuStart(text: string): boolean {
  return /<UpdateVariable(?:variable)?\s*>/i.test(extractFinalMvuBlock(text));
}

export function stripMvuBlocks(text: string): string {
  return text
    .replace(/<UpdateVariable(?:variable)?\s*>[\s\S]*?(?:<\/UpdateVariable(?:variable)?\s*>|$)/gi, '')
    .replace(/<正文>([\s\S]*?)(?:<\/正文>|$)/g, '$1')
    .replace(/<\/?正文>/g, '')
    .replace(/<(?:Analysis|JSONPatch)\s*>[\s\S]*?(?:<\/(?:Analysis|JSONPatch)\s*>|$)/gi, '')
    .replace(/<\/?(?:UpdateVariable(?:variable)?|Analysis|JSONPatch)?$/i, '');
}

export function inspectMvuCode(text: string): { code: string; error?: string; expected: boolean } {
  text = text
    .replace(/<UpdateVariablevariable\s*>/gi, '<UpdateVariable>')
    .replace(/<\/UpdateVariablevariable\s*>/gi, '</UpdateVariable>');
  const block = [...text.matchAll(/<JSONPatch>([\s\S]*?)<\/JSONPatch>/gi)].at(-1);
  if (block) {
    const code = block[1].replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, '').trim();
    try {
      const patches: unknown = JSON.parse(code);
      if (!Array.isArray(patches)) throw new Error('JSON Patch 必须是数组');
      for (const patch of patches) {
        if (
          !patch ||
          typeof patch !== 'object' ||
          !['add', 'replace', 'remove'].includes(patch.op) ||
          typeof patch.path !== 'string' ||
          !patch.path.startsWith('/') ||
          (patch.op !== 'remove' && !Object.hasOwn(patch, 'value'))
        )
          throw new Error('更新操作的类型、路径或值不完整');
      }
      return { code: block[0], expected: patches.length > 0 };
    } catch (error) {
      return { code: block[0], expected: true, error: error instanceof Error ? error.message : '更新代码无法解析' };
    }
  }
  if (/<(?:JSONPatch|UpdateVariable)\b/i.test(text) && !/_\.(?:set|add|insert|delete)\s*\(/.test(text))
    return {
      code: text.match(/<UpdateVariable>[\s\S]*/i)?.[0] || text,
      expected: true,
      error: '变量更新标签不完整或缺少 JSONPatch',
    };
  const legacy = text.match(/_\.(?:set|add|insert|delete)\s*\([\s\S]*/)?.[0];
  return { code: legacy || '', expected: !!legacy };
}
