import { useEffect, useState } from 'react';
import { Check, ChevronDown, Eye, Plus, RefreshCw, Save, Trash2, X } from 'lucide-react';
import { ForumGenerationConfig } from '../../utils/forumGeneration';
import { ForumCategory, ForumCategorySyncPreview, loadForumCategoryDescriptions, previewForumCategorySync, syncForumCategoryWorldbook } from '../../utils/forumCategories';
import { showToast } from '../ui/Toast';
import { CenterModal } from '../ui/Modal';

function createCategory(): ForumCategory {
  return { id: `custom-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, name: '新分类', description: '', enabled: true, weight: 20 };
}

export function ForumCategorySettings({ config, onChange }: { config: ForumGenerationConfig; onChange: (patch: Partial<ForumGenerationConfig>) => void }) {
  const [categories, setCategories] = useState<ForumCategory[]>(config.categories);
  const [preview, setPreview] = useState<ForumCategorySyncPreview | null>(null);
  const [busy, setBusy] = useState(false);
  const [reading, setReading] = useState(false);
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());

  useEffect(() => { setCategories(config.categories); }, [config.categories]);

  const toggleExpanded = (id: string) => setExpandedIds(current => {
    const next = new Set(current);
    if (next.has(id)) next.delete(id); else next.add(id);
    return next;
  });

  const commit = (next: ForumCategory[]) => { setCategories(next); onChange({ categories: next }); };
  const addCategory = () => {
    if (categories.length >= 20) { showToast('最多可添加 20 个分类', 'info'); return; }
    const category = createCategory();
    let suffix = 1;
    while (categories.some(item => item.name === category.name)) category.name = `新分类 ${suffix++}`;
    commit([...categories, category]);
    setExpandedIds(current => new Set([...current, category.id]));
  };
  const updateAt = (index: number, patch: Partial<ForumCategory>) => commit(categories.map((category, current) => {
    if (current !== index) return category;
    const next = { ...category, ...patch };
    if (patch.name !== undefined && patch.name.trim() !== category.name.trim()) {
      next.aliases = [...new Set([...(category.aliases || []), category.name.trim()].filter(Boolean))].slice(-10);
    }
    return next;
  }));

  const renameCategory = (index: number) => {
    const category = categories[index];
    const previous = config.categories.find(item => item.id === category.id);
    const name = category.name.trim();
    if (!name || name === '全部' || categories.some((item, current) => current !== index && item.name.trim() === name)) {
      setCategories(config.categories);
      showToast('分类名称不能为空、重复或使用“全部”', 'info');
      return;
    }
    commit(categories.map((item, current) => current === index ? {
      ...item, name,
      aliases: [...new Set([...(previous?.aliases || []), ...(previous && previous.name !== name ? [previous.name] : [])])],
    } : item));
  };

  const handleReadWorldbook = async () => {
    setReading(true);
    try { commit(await loadForumCategoryDescriptions(categories)); showToast('已读取已同步的分类说明', 'success'); }
    catch (error) { showToast(error instanceof Error ? error.message : '读取分类世界书失败', 'error'); }
    finally { setReading(false); }
  };

  const handlePreview = async () => {
    if (!categories.length) { showToast('请至少添加一个论坛分类', 'info'); return; }
    setBusy(true);
    try { setPreview(await previewForumCategorySync(categories)); }
    catch (error) { showToast(error instanceof Error ? error.message : '无法读取分类世界书', 'error'); }
    finally { setBusy(false); }
  };

  const handleSync = async () => {
    if (!preview) return;
    setBusy(true);
    try { await syncForumCategoryWorldbook(preview, categories); setPreview(null); showToast('分类说明已同步到世界书', 'success'); }
    catch (error) { showToast(error instanceof Error ? error.message : '同步分类世界书失败', 'error'); }
    finally { setBusy(false); }
  };

  const enabledWeight = categories.filter(category => category.enabled && category.weight > 0).reduce((sum, category) => sum + category.weight, 0);

  return <div className="space-y-3 border-t border-border-default/50 pt-3">
    <div className="flex items-center justify-between gap-2"><div><div className="text-xs font-semibold text-text-primary">论坛分类与生成占比</div><p className="mt-1 text-[10px] leading-relaxed text-text-secondary">启用分类按权重参与生成。只保留一个启用分类即可只生成该分类。</p></div><button type="button" onClick={addCategory} className="flex shrink-0 items-center gap-1 rounded-lg border border-border-default px-2.5 py-2 text-xs font-semibold text-text-primary transition-transform active:scale-95 hover:bg-surface"><Plus className="h-3.5 w-3.5" />添加</button></div>
    <div className="flex items-center justify-between rounded-xl border border-border-default bg-surface px-3 py-2 text-[10px] text-text-secondary"><span>当前启用权重：{enabledWeight}</span><span>{categories.length} 个分类</span></div>
    <div className="space-y-2">{categories.map((category, index) => { const expanded = expandedIds.has(category.id); return <div key={category.id} className="rounded-xl border border-border-default bg-surface p-3"><div className="flex items-center gap-2"><input type="checkbox" checked={category.enabled} onChange={event => updateAt(index, { enabled: event.target.checked })} aria-label={`启用${category.name}`} /><input value={category.name} onChange={event => { const name = event.target.value.slice(0, 24); setCategories(current => current.map((item, position) => position === index ? { ...item, name } : item)); }} onBlur={() => renameCategory(index)} onKeyDown={event => { if (event.key === 'Enter') event.currentTarget.blur(); }} className="min-w-0 flex-1 rounded-lg border border-border-default bg-surface-solid px-2.5 py-2 text-xs font-semibold text-text-primary outline-none focus:border-[color:var(--action-text)]" aria-label="分类名称" /><label className="flex shrink-0 items-center gap-1 text-[10px] text-text-secondary">权重<input type="number" min={0} max={100} value={category.weight} onChange={event => updateAt(index, { weight: Math.min(100, Math.max(0, Number(event.target.value) || 0)) })} className="w-14 rounded-lg border border-border-default bg-surface-solid px-2 py-2 text-center text-xs text-text-primary outline-none" /></label><button type="button" onClick={() => toggleExpanded(category.id)} aria-expanded={expanded} aria-label={`${expanded ? '收起' : '展开'}${category.name}说明`} className="rounded-lg p-2 text-text-secondary transition-colors hover:bg-surface-solid hover:text-text-primary"><ChevronDown className={`h-3.5 w-3.5 transition-transform ${expanded ? 'rotate-180' : ''}`} /></button><button type="button" onClick={() => commit(categories.filter((_, current) => current !== index))} aria-label={`删除${category.name}`} className="rounded-lg p-2 text-text-secondary transition-colors hover:bg-surface-solid hover:text-rose-500"><Trash2 className="h-3.5 w-3.5" /></button></div>{expanded && <textarea value={category.description} onChange={event => updateAt(index, { description: event.target.value.slice(0, 4000) })} placeholder="分类世界书说明：内容范围、口吻、常见参与者、禁忌……" rows={4} className="mt-2 max-h-32 w-full resize-none overflow-y-auto rounded-lg border border-border-default/70 bg-surface-solid/70 px-2.5 py-2 text-[11px] leading-relaxed text-text-primary outline-none [scrollbar-color:var(--border-default)_transparent] [scrollbar-width:thin] placeholder:text-text-secondary focus:border-[color:var(--action-text)]" />}</div>; })}{!categories.length && <div className="rounded-xl border border-dashed border-border-default px-3 py-5 text-center text-xs text-text-secondary">还没有分类，请先添加一个。</div>}</div>
    <div className="grid grid-cols-2 gap-2"><button type="button" disabled={reading || !categories.length} onClick={() => void handleReadWorldbook()} className="flex items-center justify-center gap-1.5 rounded-xl border border-border-default bg-surface py-2.5 text-xs font-semibold text-text-primary disabled:opacity-50"><RefreshCw className={`h-3.5 w-3.5 ${reading ? 'animate-spin' : ''}`} />读取世界书说明</button><button type="button" disabled={busy || !categories.length} onClick={() => void handlePreview()} className="flex items-center justify-center gap-1.5 rounded-xl border border-border-default bg-surface py-2.5 text-xs font-semibold text-text-primary disabled:opacity-50"><Eye className="h-3.5 w-3.5" />预览同步内容</button></div>
    <p className="text-[10px] leading-relaxed text-text-secondary">同步只会更新带有“校园论坛分类”标记的条目，普通世界书内容不会被覆盖。</p>
    <CenterModal isOpen={Boolean(preview)} onClose={() => { if (!busy) setPreview(null); }} className="w-full max-w-md"><div className="flex items-center justify-between border-b border-border-default p-4"><div><h3 className="font-bold text-text-primary">确认同步分类世界书</h3><p className="mt-1 text-[10px] text-text-secondary">目标：{preview?.book}</p></div><button type="button" disabled={busy} onClick={() => setPreview(null)} className="p-1 text-text-secondary"><X className="h-4 w-4" /></button></div><div className="max-h-[55vh] space-y-2 overflow-y-auto p-4">{preview?.changes.map(change => <div key={change.id} className="rounded-xl border border-border-default bg-surface p-3"><div className="flex items-center gap-2 text-xs font-semibold text-text-primary"><Check className="h-3.5 w-3.5 text-emerald-500" />{change.name}</div><p className="mt-2 whitespace-pre-wrap break-words text-[11px] leading-relaxed text-text-secondary">{change.content || '（空说明，仅同步分类条目）'}</p></div>)}</div><div className="flex gap-2 border-t border-border-default p-4"><button type="button" disabled={busy} onClick={() => setPreview(null)} className="flex-1 rounded-xl border border-border-default py-2.5 text-xs font-semibold text-text-secondary">取消</button><button type="button" disabled={busy} onClick={() => void handleSync()} className="flex-1 rounded-xl bg-[color:var(--action-text)] py-2.5 text-xs font-semibold text-white"><Save className="mr-1 inline h-3.5 w-3.5" />{busy ? '同步中…' : '确认同步'}</button></div></CenterModal>
  </div>;
}
