import { useCallback, useEffect, useState } from 'react';
import { applyCampusTheme, CampusTheme, loadCampusTheme, saveCampusTheme } from '../utils/themeStore';

let snapshot: CampusTheme = loadCampusTheme();
const listeners = new Set<() => void>();

function emit() {
  listeners.forEach(listener => listener());
}

export function setCampusTheme(theme: CampusTheme) {
  snapshot = theme;
  saveCampusTheme(theme);
  applyCampusTheme(theme);
  emit();
}

export function useCampusTheme() {
  const [theme, setTheme] = useState<CampusTheme>(snapshot);

  useEffect(() => {
    applyCampusTheme(snapshot);
    const listener = () => setTheme(snapshot);
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  }, []);

  const changeTheme = useCallback((next: CampusTheme) => {
    setCampusTheme(next);
  }, []);

  return { theme, setTheme: changeTheme, isDark: theme === 'dark' };
}
